import { Component, input } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Solicitud } from '../../../../models/solicitud';
import { SolicitudAccion } from '../../../../models/solicitud.accion';

@Component({
  selector: 'app-solicitud-historial-acciones',
  imports: [CommonModule,],
  templateUrl: './solicitud-historial-acciones.html'
})
export class SolicitudHistorialAcciones {
  /** Solicitud a mostrar */
  solicitud = input.required<Solicitud>();

  /**
   * Formatea una fecha para visualización
   */
  formatDate(dateString: string | Date | undefined): string {
    if (!dateString) {
      return 'No disponible';
    }
    const date = typeof dateString === 'string' ? new Date(dateString) : dateString;
    return date.toLocaleDateString('es-MX', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

    /**
   * Calcula la duración en días de una acción
   */
  getDuracionDias(accion: SolicitudAccion): number {
    if (!accion.fecha_inicio || !accion.fecha_fin) return 0;

    const inicio = new Date(accion.fecha_inicio);
    const fin = new Date(accion.fecha_fin);
    const diferencia = fin.getTime() - inicio.getTime();

    return Math.ceil(diferencia / (1000 * 60 * 60 * 24));
  }
}