import { Injectable } from "@angular/core";
import { SuperService } from "./super.service";
import { Solicitud, CrearSolicitudRequest, ActualizarSolicitudRequest, SolicitudEstatus } from "../models/solicitud";
import { firstValueFrom } from "rxjs";
import { StandarResponse } from "../services/api/api-service.service";

@Injectable({
    providedIn: 'root'
})
export class SolicitudService extends SuperService<Solicitud> {
    model = 'solicitudes'
    protected override columns: (keyof Solicitud)[] = [
        'created_by',
        'descripcion_problema',
        'fecha_inicio_problematica',
        'empresa_id'
    ]

    /**
     * Crea una nueva solicitud con múltiples archivos de evidencia PDF
     *
     * @param datosSolicitud - Datos de la solicitud (descripcion_problema, fecha_inicio_problematica)
     * @param evidencias - Array opcional de archivos PDF para evidencias
     * @param loader - Muestra loader global animado (por defecto true)
     * @returns Promise con la solicitud creada
     */
    async crearSolicitud(
        datosSolicitud: CrearSolicitudRequest,
        evidencias?: File[],
        loader = true
    ): Promise<Solicitud | undefined> {
        const formData = new FormData();

        // Agregar datos de la solicitud como JSON string
        formData.append('data', JSON.stringify(datosSolicitud));

        // Agregar archivos PDF al campo 'evidencias'
        if (evidencias && evidencias.length > 0) {
            evidencias.forEach((archivo, index) => {
                formData.append(`evidencias[${index}]`, archivo);
            });
        }

        // Usar postFormData directamente del API service
        return (await firstValueFrom(this.api.postFormData<Solicitud>(this.url(), formData, loader))).data;
    }

    /**
     * Actualiza una solicitud y permite que el UE agregue mas archivo o múltiples archivos de evidencia PDF
     *
     * @param datosSolicitud - Datos de la solicitud (descripcion_problema, fecha_inicio_problematica)
     * @param evidencias - Array opcional de archivos PDF para evidencias
     * @param loader - Muestra loader global animado (por defecto true)
     * @returns Promise con la solicitud creada
     */
    async actualizarSolicitud(
        solicitudId: number,
        datosSolicitud: ActualizarSolicitudRequest,
        evidencias?: File[],
        loader = true
    ): Promise<Solicitud | undefined> {
        const formData = new FormData();

        // Agregar datos de la solicitud como JSON string
        formData.append('data', JSON.stringify(datosSolicitud));

        // Agregar archivos PDF al campo 'evidencias'
        if (evidencias && evidencias.length > 0) {
            evidencias.forEach((archivo, index) => {
                formData.append(`evidencias[${index}]`, archivo);
            });
        }

        // Usar postFormData directamente del API service
        return (await firstValueFrom(this.api.postFormData<Solicitud>(this.url() + '/' + solicitudId + '/agregar-evidencias', formData, loader))).data;
    }

    /**
     * Cambia el estatus de una solicitud a "RESUELTA"
     *
     * @param solicitudId - ID de la solicitud a resolver
     * @returns Promise con la solicitud actualizada
     */
    async marcarComoResuelta(solicitudId: number): Promise<Solicitud | null> {
        const resultado = await this.update(solicitudId, {
            estatus: SolicitudEstatus.RESUELTA
        });
        return resultado.status ? (await this.find(solicitudId)) || null : null;
    }

    /**
     * Obtiene las solicitudes asignadas a un usuario específico.
     *
     * @param usuarioId - El ID del usuario.
     * @returns Promise con la lista de solicitudes.
     */
    async getSolicitudesByUsuarioId(usuarioId: number): Promise<StandarResponse<Solicitud[]>> {
        return this.get({
            conditionals: {
                asignado_a: usuarioId,
            },
            paginator: {
                page: 1,
                per_page: 100 // Get up to 100 assigned requests
            }
        });
    }
}