import { Component, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { SolicitudResueltaService, FiltrosSolicitudesResueltas } from '../../../shared/solicitudes-resueltas-list/services/solicitud-resuelta.service';
import { SolicitudCatalogoService } from '../../../../../controllers/solicitud-catalogo.service';
import { SolicitudTematicaService } from '../../../../../controllers/solicitud.tematica.service';
import { SolicitudGobiernoNivelService } from '../../../../../controllers/solicitud.gobierno.nivel.service';
import { SolicitudTipoService } from '../../../../../controllers/solicitud.tipo.service';

@Component({
  selector: 'app-solicitudes-resueltas-reporte',
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './solicitudes-resueltas-reporte.html',
  styleUrl: './solicitudes-resueltas-reporte.css'
})
export class SolicitudesResueltasReporte {
  private fb = inject(FormBuilder);
  private solicitudResueltaService = inject(SolicitudResueltaService);
  private catalogoService = inject(SolicitudCatalogoService);
  private tematicaService = inject(SolicitudTematicaService);
  private gobiernoNivelService = inject(SolicitudGobiernoNivelService);
  private tipoService = inject(SolicitudTipoService);

  // Formulario de filtros
  reporteForm: FormGroup;

  // Estados
  isLoading = false;
  showSuccessMessage = false;
  showError = false;
  errorMessage = '';

  // Catálogos
  tematicas: { id: number; nombre: string }[] = [];
  nivelesGobierno: { id: number; nombre: string }[] = [];
  tiposSolicitud: { id: number; nombre: string }[] = [];

  constructor() {
    this.reporteForm = this.fb.group({
      folio: [''],
      rfc: ['', [Validators.pattern(/^[A-Z0-9]{13}$/)]],
      empresa: [''],
      tematica_id: [''],
      gobierno_nivel_id: [''],
      tipo_id: [''],
      fecha_inicio: [''],
      fecha_fin: ['']
    });

    this.cargarCatalogos();
  }

  /**
   * Carga los catálogos necesarios para los filtros
   */
  async cargarCatalogos(): Promise<void> {
    try {
      // Cargar trámites
      const tematicasResponse = await this.tematicaService.get();
      if (tematicasResponse.status && tematicasResponse.data) {
        this.tematicas = tematicasResponse.data;
      }

      // Cargar niveles de gobierno
      const nivelesResponse = await this.gobiernoNivelService.get();
      if (nivelesResponse.status && nivelesResponse.data) {
        this.nivelesGobierno = nivelesResponse.data;
      }

      // Cargar tipos de solicitud
      const tiposResponse = await this.tipoService.get();
      if (tiposResponse.status && tiposResponse.data) {
        this.tiposSolicitud = tiposResponse.data;
      }
    } catch (error: unknown) {
      console.error('Error cargando catálogos:', error);
    }
  }

  /**
   * Valida que la fecha fin sea posterior a la fecha inicio
   */
  validarFechas(): void {
    const fechaInicio = this.reporteForm.get('fecha_inicio')?.value;
    const fechaFin = this.reporteForm.get('fecha_fin')?.value;

    if (fechaInicio && fechaFin && fechaFin < fechaInicio) {
      this.reporteForm.get('fecha_fin')?.setErrors({ fechaInvalida: true });
    }
  }

  /**
   * Genera y descarga el reporte Excel
   */
  descargarReporte(): void {
    if (this.reporteForm.invalid) {
      this.reporteForm.markAllAsTouched();
      return;
    }

    this.isLoading = true;
    this.showSuccessMessage = false;
    this.showError = false;

    const filtros: FiltrosSolicitudesResueltas = this.reporteForm.value;

    // Eliminar campos vacíos
    Object.keys(filtros).forEach(key => {
      if (!filtros[key as keyof FiltrosSolicitudesResueltas]) {
        delete filtros[key as keyof FiltrosSolicitudesResueltas];
      }
    });

    this.solicitudResueltaService.generarReporteExcel(filtros).subscribe({
      next: (blob: Blob) => {
        this.descargarArchivo(blob);
        this.isLoading = false;
        this.showSuccessMessage = true;
        setTimeout(() => {
          this.showSuccessMessage = false;
        }, 3000);
      },
      error: (error) => {
        this.isLoading = false;
        this.showError = true;
        this.errorMessage = 'Error al generar el reporte. Intente nuevamente.';
        console.error('Error descargando reporte:', error);
      }
    });
  }

  /**
   * Descarga el archivo blob en el navegador
   */
  private descargarArchivo(blob: Blob): void {
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;

    // Generar nombre de archivo con fecha
    const fecha = new Date().toISOString().split('T')[0];
    const hora = new Date().toTimeString().split(' ')[0].replace(/:/g, '-');
    const fileName = `reporte_solicitudes_resueltas_${fecha}_${hora}.xlsx`;

    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    window.URL.revokeObjectURL(url);
  }

  /**
   * Limpia todos los filtros del formulario
   */
  limpiarFiltros(): void {
    this.reporteForm.reset();
    this.showError = false;
    this.showSuccessMessage = false;
  }

  /**
   * Getters para validación de formulario
   */
  get folio() { return this.reporteForm.get('folio'); }
  get rfc() { return this.reporteForm.get('rfc'); }
  get empresa() { return this.reporteForm.get('empresa'); }
  get tematica_id() { return this.reporteForm.get('tematica_id'); }
  get gobierno_nivel_id() { return this.reporteForm.get('gobierno_nivel_id'); }
  get tipo_id() { return this.reporteForm.get('tipo_id'); }
  get fecha_inicio() { return this.reporteForm.get('fecha_inicio'); }
  get fecha_fin() { return this.reporteForm.get('fecha_fin'); }
}