import { Component, inject, Input, OnChanges, SimpleChanges } from '@angular/core';
import { SolicitudComentario } from '../../../../models/solicitud.comentario';
import { SolicitudComentarioService } from '../../../../controllers/solicitud-comentario.service';
import { LocalStorageService } from '../../../../services/localStorage/local-storage.service';
import { DatePipe } from '@angular/common';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-comentarios-box',
  imports: [
    FormsModule
  ],
  templateUrl: './comentarios-box.html',
  styleUrl: './comentarios-box.css'
})
export class ComentariosBox implements OnChanges {
  @Input() solicitudId!: number

  comentarios: SolicitudComentario[] = []

  loading = false

  // Formulario de nuevo comentario
  nuevoComentario = '';
  submittingComment = false;

  //services
  private comentarioService = inject(SolicitudComentarioService)
  private storage = inject(LocalStorageService)


  ngOnChanges(changes: SimpleChanges): void {
    if (changes['solicitudId']) {
      this.loadComentarios()
    }
  }

  private async loadComentarios() {
    this.loading = true;
    // Cargar comentarios por separado para asegurar orden cronológico
    this.comentarios = await this.comentarioService.getComentariosConCreador(this.solicitudId, false);
    // Ordenar comentarios por fecha de creación (más antiguos primero)
    this.comentarios.sort((a, b) => new Date(a.created_at!).getTime() - new Date(b.created_at!).getTime());

    this.loading = false;
  }

  /**
 * Agrega un nuevo comentario a la solicitud
 */
  async agregarComentario() {

    this.submittingComment = true;

    const nuevoComentarioData = {
      contenido: this.nuevoComentario.trim(),
      solicitud_id: this.solicitudId
    };

    const comentarioCreado = await this.comentarioService.new(nuevoComentarioData, false);

    if (comentarioCreado) {
      // Recargar comentarios para incluir el nuevo
      this.comentarios = await this.comentarioService.getComentariosConCreador(this.solicitudId, false);
      this.comentarios.sort((a, b) => new Date(a.created_at!).getTime() - new Date(b.created_at!).getTime());

      // Limpiar formulario
      this.nuevoComentario = '';
    }

    this.submittingComment = false;
  }

  /**
 * Formatea una fecha para visualización
 */
  formatDate(dateString: string | Date | undefined): string {
    if (!dateString) {
      return 'No disponible';
    }
    const datePipe = new DatePipe('en-US');
    return datePipe.transform(dateString, 'dd/MM/yyyy HH:mm') || 'No disponible';
  }

  /**
 * Verifica si un comentario es del usuario actual
 */
  esMiComentario(comentario: SolicitudComentario): boolean {
    const user = this.storage.getUser()?.user
    return !!user && comentario.created_by === user.id;
  }
}
