import { Injectable, inject } from '@angular/core';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Observable, throwError } from 'rxjs';
import { catchError, map } from 'rxjs/operators';
import { environment } from '../../../../environments/environment';
import { HttpHeadersService } from '../../../services/http.headers.service';

// Interfaces para las respuestas del API
export interface SolicitudPendiente {
  id: number;
  empresa_razon_social: string;
  empresa_nombre_solicitante: string;
  descripcion_problema: string;
  solicitud_tipo_id: number;
  solicitud_tematica_id: number;
  solicitud_gobierno_nivel_id: number;
  estatus: string;
  created_at: string;
  empresa?: {
    id: number;
    razon_social: string;
    nombre_solicitante: string;
  };
  solicitudTipo?: {
    id: number;
    nombre: string;
  };
  solicitudTematica?: {
    id: number;
    nombre: string;
  };
  solicitudGobiernoNivel?: {
    id: number;
    nombre: string;
  };
  creador?: {
    id: number;
    name: string;
    email: string;
  };
}

export interface UsuarioSei {
  id: number;
  name: string;
  email: string;
  cargo?: string;
  departamento?: string;
  activo: boolean;
  solicitudes_asignadas_count?: number;
}

export interface AsignacionRequest {
  usuario_sei_id: number;
  notas?: string;
}

export interface AsignacionResponse {
  status: boolean;
  message: string;
  data?: {
    id: number;
    solicitud_id: number;
    usuario_sei_id: number;
    asignado_por_id: number;
    fecha_asignacion: string;
    estatus: string;
    notas?: string;
    usuario_sei?: {
      id: number;
      name: string;
      email: string;
    };
    asignado_por?: {
      id: number;
      name: string;
      email: string;
    };
  };
  errors?: Record<string, string[]>;
}

export interface EstadisticasAsignacion {
  solicitudes_pendientes: number;
  total_asignaciones: number;
  asignaciones_activas: number;
  asignaciones_reasignadas: number;
  asignaciones_completadas: number;
  top_usuarios: TopUsuario[];
}

export interface TopUsuario {
  usuario: {
    id: number;
    name: string;
    email: string;
  };
  total_asignaciones: number;
}

export interface HistorialAsignacion {
  id: number;
  solicitud_id: number;
  usuario_sei_id: number;
  asignado_por_id: number;
  fecha_asignacion: string;
  estatus: string;
  notas?: string;
  created_at: string;
  updated_at: string;
  usuario_sei?: {
    id: number;
    name: string;
    email: string;
  };
  asignado_por?: {
    id: number;
    name: string;
    email: string;
  };
}

export interface PaginatedResponse<T> {
  status: boolean;
  message: string;
  data: T[];
  pagination: {
    page: number;
    per_page: number;
    total_items: number;
    total_pages: number;
  };
}

@Injectable({
  providedIn: 'root'
})
export class SolicitudAsignacionService {
  private httpHeaders = inject(HttpHeadersService)
  private http = inject(HttpClient);
  private apiUrl = environment.api_url;

  /**
   * Obtener solicitudes pendientes de asignar
   */
  getSolicitudesPendientes(params?: {
    page?: number;
    per_page?: number;
    id?: number;
    search?: string;
    estatus?: string;
    solicitud_tipo_id?: number;
    solicitud_tematica_id?: number;
    solicitud_gobierno_nivel_id?: number;
    fecha_creacion_desde?: string;
    fecha_creacion_hasta?: string;
  }): Observable<PaginatedResponse<SolicitudPendiente>> {
    const queryParams: Record<string, string> = {}

    if (params?.page) queryParams['page'] = params.page.toString();
    if (params?.per_page) queryParams['per_page'] = params.per_page.toString();
    if (params?.id) queryParams['id'] = params.id.toString();
    if (params?.search) queryParams['search'] = params.search;
    if (params?.solicitud_tipo_id) queryParams['solicitud_tipo_id'] = params.solicitud_tipo_id.toString();
    if (params?.solicitud_tematica_id) queryParams['solicitud_tematica_id'] = params.solicitud_tematica_id.toString();
    if (params?.solicitud_gobierno_nivel_id) queryParams['solicitud_gobierno_nivel_id'] = params.solicitud_gobierno_nivel_id.toString();
    if (params?.fecha_creacion_desde) {
      queryParams['fecha_desde'] = params.fecha_creacion_desde;
    }
    if (params?.fecha_creacion_hasta) {
      queryParams['fecha_hasta'] = params.fecha_creacion_hasta;
    }
    if (params?.estatus) queryParams['estatus'] = params.estatus;

    const url = `${this.apiUrl}/api/solicitud-asignacion`;

    const headers = this.httpHeaders.createAuthHeaders()

    return this.http.get<PaginatedResponse<SolicitudPendiente>>(url, { headers, params: queryParams }).pipe(
      map(response => {
        console.log('Solicitudes pendientes obtenidas:', response);
        return response;
      }),
      catchError(this.handleError)
    );
  }

  /**
   * Asignar solicitud a usuario SEI
   */
  asignarSolicitud(solicitudId: number, asignacion: AsignacionRequest): Observable<AsignacionResponse> {
    const headers = this.httpHeaders.createAuthHeaders()

    return this.http.post<AsignacionResponse>(`${this.apiUrl}/api/solicitud-asignacion/${solicitudId}/asignar`, asignacion, { headers }).pipe(
      map(response => {
        console.log('Solicitud asignada exitosamente:', response);
        return response;
      }),
      catchError(this.handleError)
    );
  }

  /**
   * Reasignar solicitud a otro usuario SEI
   */
  reasignarSolicitud(solicitudId: number, asignacion: AsignacionRequest): Observable<AsignacionResponse> {
    const headers = this.httpHeaders.createAuthHeaders()

    return this.http.post<AsignacionResponse>(`${this.apiUrl}/api/solicitud-asignacion/${solicitudId}/reasignar`, asignacion, { headers }).pipe(
      map(response => {
        console.log('Solicitud reasignada exitosamente:', response);
        return response;
      }),
      catchError(this.handleError)
    );
  }

  /**
   * Obtener usuarios SEI disponibles para asignación
   */
  getUsuariosDisponibles(): Observable<{ status: boolean; message: string; data: UsuarioSei[] }> {
    const headers = this.httpHeaders.createAuthHeaders()

    return this.http.get<{ status: boolean; message: string; data: UsuarioSei[] }>(`${this.apiUrl}/api/solicitud-asignacion/usuarios-disponibles`, { headers }).pipe(
      map(response => {
        console.log('Usuarios SEI disponibles:', response);
        return response;
      }),
      catchError(this.handleError)
    );
  }

  /**
   * Obtener estadísticas de asignaciones
   */
  getEstadisticas(): Observable<{ status: boolean; message: string; data: EstadisticasAsignacion }> {
    const headers = this.httpHeaders.createAuthHeaders()

    return this.http.get<{ status: boolean; message: string; data: EstadisticasAsignacion }>(`${this.apiUrl}/api/solicitud-asignacion/estadisticas`, { headers }).pipe(
      map(response => {
        console.log('Estadísticas obtenidas:', response);
        return response;
      }),
      catchError(this.handleError)
    );
  }

  /**
   * Obtener historial de asignaciones de una solicitud
   */
  getHistorialAsignaciones(solicitudId: number): Observable<{ status: boolean; message: string; data: HistorialAsignacion[] }> {
    const headers = this.httpHeaders.createAuthHeaders()

    return this.http.get<{ status: boolean; message: string; data: HistorialAsignacion[] }>(`${this.apiUrl}/api/solicitud-asignacion/${solicitudId}/historial`, { headers }).pipe(
      map(response => {
        console.log('Historial de asignaciones obtenido:', response);
        return response;
      }),
      catchError(this.handleError)
    );
  }

  /**
   * Obtener detalles de una solicitud específica
   */
  getSolicitudDetalle(solicitudId: number): Observable<{ status: boolean; message: string; data: SolicitudPendiente }> {
    return this.http.get<{ status: boolean; message: string; data: SolicitudPendiente }>(`${this.apiUrl}/api/solicitudes/${solicitudId}`).pipe(
      map(response => {
        console.log('Detalle de solicitud obtenido:', response);
        return response;
      }),
      catchError(this.handleError)
    );
  }

  /**
   * Manejo de errores HTTP
   */
  private handleError(error: HttpErrorResponse): Observable<never> {
    let errorMessage = 'Error desconocido';
    let errors: Record<string, string[]> = {};

    if (error.error instanceof ErrorEvent) {
      // Error del cliente
      errorMessage = `Error: ${error.error.message}`;
    } else {
      // Error del servidor
      switch (error.status) {
        case 400:
          errorMessage = 'Solicitud inválida';
          break;
        case 401:
          errorMessage = 'No autorizado';
          break;
        case 403:
          errorMessage = 'Acceso denegado';
          break;
        case 404:
          errorMessage = 'Recurso no encontrado';
          break;
        case 422:
          errorMessage = 'Error de validación';
          if (error.error?.errors) {
            errors = error.error.errors;
          }
          break;
        case 429:
          errorMessage = 'Demasiados intentos. Por favor, espera un momento';
          break;
        case 500:
          errorMessage = 'Error del servidor. Por favor, intenta más tarde';
          break;
        default:
          errorMessage = error.error?.message || `Error del servidor: ${error.status}`;
      }
    }

    console.error('Error en SolicitudAsignacionService:', {
      status: error.status,
      message: errorMessage,
      errors: errors,
      fullError: error
    });

    return throwError(() => ({
      status: false,
      message: errorMessage,
      errors: errors
    }));
  }

  /**
   * Formatear errores para mostrar en UI
   * Maneja diferentes formatos de errores comunes en APIs
   */
  formatErrors(errors: Record<string, string[]> | unknown): string[] {
    // Caso: no es un objeto o es null
    if (typeof errors !== 'object' || errors === null) {
      return [];
    }

    // Caso: ya es un array de strings (formato plano)
    if (Array.isArray(errors) && errors.every(item => typeof item === 'string')) {
      return errors as string[];
    }

    // Caso: Record<string, string[]> (formato de validación común)
    if (this.isRecordWithStringArrays(errors)) {
      const formattedErrors: string[] = [];

      for (const [, messages] of Object.entries(errors)) {
        if (Array.isArray(messages)) {
          for (const message of messages) {
            if (typeof message === 'string' && message.trim() !== '') {
              formattedErrors.push(message.trim());
            }
          }
        }
      }

      return formattedErrors;
    }

    // Caso: Record<string, string> (formato simple)
    if (this.isRecordWithStrings(errors)) {
      const formattedErrors: string[] = [];

      for (const [, message] of Object.entries(errors)) {
        if (typeof message === 'string' && message.trim() !== '') {
          formattedErrors.push(message.trim());
        }
      }

      return formattedErrors;
    }

    return [];
  }

  /**
   * Type guard para verificar si es Record<string, string[]>
   */
  private isRecordWithStringArrays(obj: unknown): obj is Record<string, string[]> {
    if (typeof obj !== 'object' || obj === null) return false;

    return Object.values(obj).every(value =>
      Array.isArray(value) && value.every(item => typeof item === 'string')
    );
  }

  /**
   * Type guard para verificar si es Record<string, string>
   */
  private isRecordWithStrings(obj: unknown): obj is Record<string, string> {
    if (typeof obj !== 'object' || obj === null) return false;

    return Object.values(obj).every(value => typeof value === 'string');
  }

  /**
   * Validar datos de asignación
   */
  validarAsignacion(asignacion: AsignacionRequest): { valid: boolean; errors: string[] } {
    const errors: string[] = [];

    if (!asignacion.usuario_sei_id || asignacion.usuario_sei_id <= 0) {
      errors.push('Debe seleccionar un usuario SEI válido');
    }

    if (asignacion.notas && asignacion.notas.length > 500) {
      errors.push('Las notas no pueden exceder 500 caracteres');
    }

    return {
      valid: errors.length === 0,
      errors
    };
  }
}