import { Pipe, PipeTransform } from '@angular/core';
import { SolicitudEstatus } from '../models/solicitud';

@Pipe({
  name: 'estatus',
  standalone: true
})
export class EstatusPipe implements PipeTransform {

  transform(value: string | undefined): string {
    if (!value) return '';

    switch (value) {
      case SolicitudEstatus.RECIBIDA:
        return 'ENVIADA';
      case SolicitudEstatus.EN_PROCESO:
        return 'EN PROCESO';
      case SolicitudEstatus.RESUELTA:
        return 'RESUELTA';
      default:
        return value;
    }
  }

}
