import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../../environments/environment';
import { HttpHeadersService } from '../services/http.headers.service';
import { Solicitud } from '../models/solicitud';
import { ClasificacionRequest } from '../models/solicitud';

export interface StandarResponse<T = unknown> {
  status: boolean;
  data?: T;
  message: string;
  per_page?: number;
  page?: number;
  total_pages?: number;
  total_items?: number;
}

interface ComentarioResponse {
  id: number;
  contenido: string;
  created_at: string;
  creador: {
    id: number;
    name: string;
  };
}

interface MarcarLeidaResponse {
  solicitud_id: number;
  notas_lectura?: string;
}

@Injectable({
  providedIn: 'root'
})
export class SolicitudAsignadaHttpService {
  private apiUrl = environment.api_url;
  private http = inject(HttpClient);
  private headersService = inject(HttpHeadersService);

  /**
   * Obtiene las solicitudes asignadas al usuario autenticado
   */
  getSolicitudesAsignadas(params?: Record<string, string | number | boolean>): Observable<StandarResponse<Solicitud[]>> {
    const url = `${this.apiUrl}/api/solicitudes-asignadas`;
    const headers = this.headersService.createAuthHeaders();

    return this.http.get<StandarResponse<Solicitud[]>>(url, {
      headers,
      params
    });
  }

  /**
   * Obtiene los detalles de una solicitud asignada específica
   */
  getDetallesSolicitudAsignada(id: number): Observable<StandarResponse<Solicitud>> {
    const url = `${this.apiUrl}/api/solicitudes-asignadas/${id}`;
    const headers = this.headersService.createAuthHeaders();

    return this.http.get<StandarResponse<Solicitud>>(url, { headers });
  }

  /**
   * Clasifica una solicitud asignada
   */
  clasificarSolicitudAsignada(id: number, datosClasificacion: ClasificacionRequest): Observable<StandarResponse<Solicitud>> {
    const url = `${this.apiUrl}/api/solicitudes-asignadas/${id}/clasificar`;
    const headers = this.headersService.createAuthHeaders();

    return this.http.put<StandarResponse<Solicitud>>(url, datosClasificacion, { headers });
  }

  /**
   * Obtiene estadísticas de las solicitudes asignadas al usuario
   */
  getEstadisticas(): Observable<StandarResponse<Record<string, unknown>>> {
    const url = `${this.apiUrl}/api/solicitudes-asignadas/estadisticas`;
    const headers = this.headersService.createAuthHeaders();

    return this.http.get<StandarResponse<Record<string, unknown>>>(url, { headers });
  }

  /**
   * Agrega un comentario a una solicitud asignada
   */
  agregarComentario(solicitudId: number, contenido: string): Observable<StandarResponse<ComentarioResponse>> {
    const url = `${this.apiUrl}/api/solicitudes-asignadas/${solicitudId}/comentarios`;
    const headers = this.headersService.createAuthHeaders();

    return this.http.post<StandarResponse<ComentarioResponse>>(url, { contenido }, { headers });
  }

  /**
   * Marca una solicitud asignada como leída
   */
  marcarComoLeida(solicitudId: number, notasLectura?: string): Observable<StandarResponse<MarcarLeidaResponse>> {
    const url = `${this.apiUrl}/api/solicitudes-asignadas/${solicitudId}/marcar-leida`;
    const headers = this.headersService.createAuthHeaders();
    const body = notasLectura ? { notas_lectura: notasLectura } : {};

    return this.http.put<StandarResponse<MarcarLeidaResponse>>(url, body, { headers });
  }
}