import { Injectable } from "@angular/core";
import { SuperService } from "./super.service";
import { SolicitudTipo } from "../models/solicitud.tipo";
import { SolicitudTematica } from "../models/solicitud.tematica";
import { SolicitudGobiernoNivel } from "../models/solicitud.gobierno.nivel";
import { SolicitudDependencia } from "../models/solicitud.dependencia";

// Clases internas para catálogos
class SolicitudTipoService extends SuperService<SolicitudTipo> {
    model = 'solicitud-tipos'
    protected override columns: (keyof SolicitudTipo)[] = ['id', 'nombre', 'descripcion']
}

class SolicitudTematicaService extends SuperService<SolicitudTematica> {
    model = 'solicitud-tematicas'
    protected override columns: (keyof SolicitudTematica)[] = ['id', 'nombre', 'descripcion']
}

class SolicitudGobiernoNivelService extends SuperService<SolicitudGobiernoNivel> {
    model = 'solicitud-gobierno-niveles'
    protected override columns: (keyof SolicitudGobiernoNivel)[] = ['id', 'nombre', 'descripcion']
}

class SolicitudDependenciaFederalService extends SuperService<SolicitudDependencia> {
    model = 'solicitud-dependencia-federal'
    protected override columns: (keyof SolicitudDependencia)[] = ['id', 'nombre', 'descripcion'];
}

class SolicitudDependenciaEstatalService extends SuperService<SolicitudDependencia> {
    model = 'solicitud-dependencia-estatal'
    protected override columns: (keyof SolicitudDependencia)[] = ['id', 'nombre', 'descripcion'];
}

/**
 * Interfaz para catálogos de clasificación
 */
export interface CatalogosClasificacion {
    tipos: SolicitudTipo[];
    tematicas: SolicitudTematica[];
    niveles_gobierno: SolicitudGobiernoNivel[];
    dependenciasFederales: SolicitudDependencia[];
    dependenciasEstatales: SolicitudDependencia[];
}

@Injectable({
    providedIn: 'root'
})
export class SolicitudCatalogoService {
    // Servicios para catálogos específicos
    private solicitudTipoService = new SolicitudTipoService();
    private solicitudTematicaService = new SolicitudTematicaService();
    private solicitudGobiernoNivelService = new SolicitudGobiernoNivelService();
    private solicitudDependenciaFederalService = new SolicitudDependenciaFederalService();
    private solicitudDependenciaEstatalService = new SolicitudDependenciaEstatalService();

    /**
     * Obtiene los catálogos necesarios para la clasificación
     *
     * @param loader - Muestra loader global animado (por defecto true)
     * @returns Promise con los catálogos de clasificación
     */
    async getCatalogos(loader = true): Promise<CatalogosClasificacion> {
        try {
            // Cargar todos los catálogos en paralelo
            const [tipos, tematicas, niveles_gobierno, dependenciasFederales, dependenciasEstatales] = await Promise.all([
                this.getSolicitudTipos(loader),
                this.getSolicitudTematicas(loader),
                this.getSolicitudGobiernoNiveles(loader),
                this.getSolicitudDependenciaFederal(loader),
                this.getSolicitudDependenciaEstatal(loader)
            ]);

            return {
                tipos,
                tematicas,
                niveles_gobierno,
                dependenciasFederales,
                dependenciasEstatales
            };
        } catch (error) {
            console.error('Error cargando catálogos:', error);
            // Retornar catálogos vacíos en caso de error
            return {
                tipos: [],
                tematicas: [],
                niveles_gobierno: [],
                dependenciasFederales: [],
                dependenciasEstatales: []
            };
        }
    }

    /**
     * Obtiene todos los tipos de solicitud activos
     *
     * @param loader - Muestra loader global animado (por defecto true)
     * @returns Promise con la lista de tipos de solicitud
     */
    async getSolicitudTipos(loader = true): Promise<SolicitudTipo[]> {
        const response = await this.solicitudTipoService.get(
            {
                conditionals: {
                    deleted_at: null,
                },
                loader
            }
        );
        return response.data || [];
    }

    /**
     * Obtiene todas las trámites de solicitud activas
     *
     * @param loader - Muestra loader global animado (por defecto true)
     * @returns Promise con la lista de trámites de solicitud
     */
    async getSolicitudTematicas(loader = true): Promise<SolicitudTematica[]> {
        const response = await this.solicitudTematicaService.get(
            {
                conditionals: {
                    deleted_at: null,
                },
                loader
            }
        );
        return response.data || [];
    }

    /**
     * Obtiene todos los niveles de gobierno activos
     *
     * @param loader - Muestra loader global animado (por defecto true)
     * @returns Promise con la lista de niveles de gobierno
     */
    async getSolicitudGobiernoNiveles(loader = true): Promise<SolicitudGobiernoNivel[]> {
        const response = await this.solicitudGobiernoNivelService.get(
            {
                conditionals: {
                    deleted_at: null,
                },
                loader
            }
        );
        return response.data || [];
    }

    /**
     * Obtiene las dependencias federales
     */
    async getSolicitudDependenciaFederal(loader = true): Promise<SolicitudDependencia[]> {
        const response = await this.solicitudDependenciaFederalService.get(
            {
                conditionals: {
                    deleted_at: null
                },
                loader
            }
        );
        return response.data || [];
    }

    /**
     * Obtiene las dependencias estatales
     */
    async getSolicitudDependenciaEstatal(loader = true): Promise<SolicitudDependencia[]> {
        const response = await this.solicitudDependenciaEstatalService.get(
            {
                conditionals: {
                    deleted_at: null
                },
                loader
            }
        );
        return response.data || [];
    }
}