import { Component, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { Solicitud } from '../../../models/solicitud';
import { SolicitudClasificacionService } from '../../../controllers/solicitud-clasificacion.service';
import { StandarResponse } from '../../../services/api/api-service.service';

/**
 * Interfaz para estadísticas de solicitudes asignadas al usuario
 */
interface EstadisticasSolicitudesAsignadas {
    total_asignadas: number;
    asignaciones_activas: number;
    completadas: number;
    por_clasificar: number;
    por_tipo: { nombre: string; total: number }[];
    por_tematica: { nombre: string; total: number }[];
}

@Component({
  selector: 'app-solicitudes-recepcion',
  imports: [CommonModule, FormsModule],
  templateUrl: './solicitudes-recepcion.html',
  styleUrl: './solicitudes-recepcion.css'
})
export class SolicitudesRecepcion implements OnInit {
  // Datos
  solicitudes: Solicitud[] = [];
  estadisticas: EstadisticasSolicitudesAsignadas | null = null;

  // Paginación y búsqueda
  currentPage = 1;
  perPage = 10;
  totalPages = 1;
  totalItems = 0;
  searchQuery = '';

  // Estados de UI
  loading = false;
  error: string | null = null;

  // Services
  private route = inject(ActivatedRoute);
  private router = inject(Router);
  private solicitudClasificacionService = inject(SolicitudClasificacionService);

  ngOnInit() {
    this.loadInitialData();
  }

  /**
   * Carga los datos iniciales (estadísticas y primera página de solicitudes)
   */
  private async loadInitialData() {
    this.loading = true;
    this.error = null;

    try {
      // Cargar estadísticas y primeras páginas en paralelo
      await Promise.all([
        this.loadEstadisticas(),
        this.loadSolicitudes()
      ]);
    } catch (error) {
      console.error('Error cargando datos iniciales:', error);
      this.error = 'Error al cargar los datos. Por favor, intente nuevamente.';
    } finally {
      this.loading = false;
    }
  }

  /**
   * Carga las estadísticas de clasificación
   */
  private async loadEstadisticas() {
    try {
      this.estadisticas = await this.solicitudClasificacionService.getEstadisticas(false);
    } catch (error) {
      console.error('Error cargando estadísticas:', error);
    }
  }

  /**
   * Carga las solicitudes pendientes de clasificación
   */
  private async loadSolicitudes() {
    try {
      const response: StandarResponse<Solicitud[]> = await this.solicitudClasificacionService.getSolicitudesPendientes(
        this.searchQuery || undefined,
        this.currentPage,
        this.perPage,
        false
      );

      this.solicitudes = response.data || [];

      // Actualizar información de paginación
      this.currentPage = response.page || 1;
      this.perPage = response.per_page || 10;
      this.totalPages = response.total_pages || 1;
      this.totalItems = response.total_items || 0;
    } catch (error) {
      console.error('Error cargando solicitudes:', error);
      throw error;
    }
  }

  /**
   * Maneja la búsqueda de solicitudes
   */
  onSearch() {
    this.currentPage = 1; // Reiniciar a la primera página
    this.loadSolicitudes();
  }

  /**
   * Maneja el cambio de página
   */
  onPageChange(page: number) {
    if (page >= 1 && page <= this.totalPages && page !== this.currentPage) {
      this.currentPage = page;
      this.loadSolicitudes();
    }
  }

  /**
   * Navega a la página de clasificación de una solicitud específica
   */
  irAClasificar(solicitudId: number) {
    this.router.navigate(['../clasificar', solicitudId], { relativeTo: this.route });
  }

  /**
   * Formatea una fecha para visualización
   */
  formatDate(dateString: string | Date): string {
    const date = typeof dateString === 'string' ? new Date(dateString) : dateString;
    return date.toLocaleDateString('es-MX', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  /**
   * Obtiene las iniciales del nombre del solicitante
   */
  getIniciales(nombre: string): string {
    return nombre
      .split(' ')
      .map(word => word.charAt(0).toUpperCase())
      .slice(0, 2)
      .join('');
  }

  /**
   * Recarga los datos
   */
  recargarDatos() {
    this.loadInitialData();
  }

  /**
   * Función para trackBy en ngFor
   */
  trackSolicitud(index: number, solicitud: Solicitud): number {
    return solicitud.id;
  }

  /**
   * Función para trackBy en paginación
   */
  trackPage(index: number, page: number | '...'): number | string {
    return page;
  }

  /**
   * Genera el rango de páginas para mostrar en la paginación
   */
  getPaginationRange(): (number | '...')[] {
    const range: (number | '...')[] = [];
    const total = this.totalPages;
    const current = this.currentPage;
    const delta = 2; // Número de páginas a mostrar antes y después de la actual

    const rangeWithDots = (start: number, end: number) => {
      for (let i = start; i <= end; i++) {
        range.push(i);
      }
    };

    if (total <= 7) {
      // Si hay 7 o menos páginas, mostrar todas
      rangeWithDots(1, total);
    } else {
      // Siempre mostrar la primera página
      range.push(1);

      if (current <= 4) {
        // Si estamos cerca del inicio
        rangeWithDots(2, Math.min(5, total - 1));
        if (total > 6) {
          range.push('...');
          range.push(total);
        }
      } else if (current >= total - 3) {
        // Si estamos cerca del final
        range.push('...');
        rangeWithDots(Math.max(total - 4, 2), total);
      } else {
        // Si estamos en medio
        range.push('...');
        rangeWithDots(current - delta, current + delta);
        range.push('...');
        range.push(total);
      }
    }

    return range;
  }
}
