import { Component, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute, Router, RouterModule } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { Solicitud, ClasificacionRequest } from '../../../models/solicitud';
import { SolicitudCatalogoService, CatalogosClasificacion } from '../../../controllers/solicitud-catalogo.service';
import { SolicitudAsignadaHttpService } from '../../../controllers/solicitud-asignada-http.service';
import { SolicitudEvidenciaService } from '../../../controllers/solicitud-evidencia.service';
import { SolicitudDependencia } from '../../../models/solicitud.dependencia';
import { TitlecasePipe } from '../../../pipes/titlecase.pipe';


@Component({
  selector: 'app-solicitudes-clasificacion',
  imports: [CommonModule, FormsModule, RouterModule, TitlecasePipe],
  templateUrl: './solicitudes-clasificacion.html'
})
export class SolicitudesClasificacion {
  // Datos
  solicitud: Solicitud | null = null;
  catalogos: CatalogosClasificacion | null = null;

  filteredDependencias: SolicitudDependencia[] = [];

  // Formulario de clasificación
  clasificacionForm: ClasificacionRequest & { otra_dependencia?: string } = {
    solicitud_tipo_id: 0,
    solicitud_tematica_id: 0,
    solicitud_tematica_otro: '',
    solicitud_gobierno_nivel_id: 0,
    solicitud_dependencia_id: 0,
    observaciones_clasificacion: '',
    otra_dependencia: ''
  };

  // Estados de UI
  loading = false;
  saving = false;
  error: string | null = null;
  success = false;

  // Validación
  formErrors: Partial<ClasificacionRequest> = {};
  touchedFields: {
    [key: string]: boolean;
    solicitud_tipo_id: boolean;
    solicitud_tematica_id: boolean;
    solicitud_tematica_otro: boolean;
    solicitud_gobierno_nivel_id: boolean;
    solicitud_dependencia_id: boolean;
    otra_dependencia: boolean;
    observaciones_clasificacion: boolean;
  } = {
      solicitud_tipo_id: false,
      solicitud_tematica_id: false,
      solicitud_tematica_otro: false,
      solicitud_gobierno_nivel_id: false,
      solicitud_dependencia_id: false,
      otra_dependencia: false,
      observaciones_clasificacion: false
    };

  // Services
  private route = inject(ActivatedRoute);
  private router = inject(Router);
  private solicitudAsignadaHttpService = inject(SolicitudAsignadaHttpService);
  private solicitudCatalogoService = inject(SolicitudCatalogoService);
  private solicitudEvidenciaService = inject(SolicitudEvidenciaService);

  constructor() {
    // Obtener el ID de la solicitud de la ruta
    const id = this.route.snapshot.paramMap.get('id');
    if (id) {
      this.cargarDatos(parseInt(id));
    } else {
      this.error = 'ID de solicitud no proporcionado';
    }
  }

  /**
   * Maneja el cambio en el campo "Orden de Gobierno"
   */
  onGobiernoNivelChange(): void {
    console.log('onGobiernoNivelChange triggered');
    console.log('Current form value:', this.clasificacionForm.solicitud_gobierno_nivel_id);

    // Only reset dependency if we are NOT loading initial data (we can check if dependency is already set and matches)
    // But for simplicity, we usually reset. However, if we are mapping data, we might trigger this.
    // Let's just reset if the user interacts.

    // Note: When loading data programmatically, we should probably manually set filteredDependencias instead of calling this,
    // or call this and then re-set the dependency ID.

    this.clasificacionForm.solicitud_dependencia_id = 0;
    this.clasificacionForm.otra_dependencia = '';
    this.touchedFields['solicitud_dependencia_id'] = false;
    this.touchedFields['otra_dependencia'] = false;
    this.onFieldChange('solicitud_gobierno_nivel_id');

    this.updateFilteredDependencias();
  }

  /**
   * Updates the filtered dependencies list based on the current government level
   */
  private updateFilteredDependencias(): void {
    const nivelId = this.clasificacionForm.solicitud_gobierno_nivel_id;
    console.log('Filtering dependencies for level ID:', nivelId);

    if (nivelId && this.catalogos) {
      // Ensure ID comparison handles string/number mismatch
      const nivel = this.catalogos.niveles_gobierno.find(n => n.id == nivelId);
      console.log('Found level:', nivel);

      const nombreNivel = nivel?.nombre.toLowerCase();
      console.log('Level name:', nombreNivel);
      console.log('Federal deps count:', this.catalogos.dependenciasFederales?.length);
      console.log('Estatal deps count:', this.catalogos.dependenciasEstatales?.length);

      if (nombreNivel && nombreNivel.includes('federal')) {
        this.filteredDependencias = this.catalogos.dependenciasFederales;
      } else if (nombreNivel && nombreNivel.includes('estatal')) {
        this.filteredDependencias = this.catalogos.dependenciasEstatales;
      } else {
        this.filteredDependencias = [];
      }
      console.log('Filtered dependencies count:', this.filteredDependencias.length);
    } else {
      this.filteredDependencias = [];
    }
  }

  /**
   * Carga todos los datos necesarios para la clasificación
   */
  private async cargarDatos(solicitudId: number) {
    this.loading = true;
    this.error = null;

    try {
      // Cargar solicitud y catálogos en paralelo
      await Promise.all([
        this.cargarCatalogos(), // Load catalogs first or in parallel
        this.cargarSolicitud(solicitudId)
      ]);

      // After both are loaded, map data
      this.mapSolicitudToForm();

    } catch (error) {
      console.error('Error cargando datos:', error);
      this.error = 'Error al cargar los datos de la solicitud';
    } finally {
      this.loading = false;
    }
  }

  /**
   * Maps existing solicitud classification data to the form
   */
  private mapSolicitudToForm() {
    if (this.solicitud && this.catalogos) {
      console.log('Mapping solicitud data to form:', this.solicitud);

      if (this.solicitud.solicitud_tipo_id) {
        this.clasificacionForm.solicitud_tipo_id = this.solicitud.solicitud_tipo_id;
      }

      if (this.solicitud.solicitud_tematica_id) {
        this.clasificacionForm.solicitud_tematica_id = this.solicitud.solicitud_tematica_id;
      }

      if (this.solicitud.solicitud_tematica_otro) {
        this.clasificacionForm.solicitud_tematica_otro = this.solicitud.solicitud_tematica_otro;
      }

      if (this.solicitud.solicitud_gobierno_nivel_id) {
        this.clasificacionForm.solicitud_gobierno_nivel_id = this.solicitud.solicitud_gobierno_nivel_id;

        // Update filtered dependencies without resetting the dependency ID
        this.updateFilteredDependencias();

        // Now set the dependency ID if it exists
        if (this.solicitud.solicitud_dependencia_id) {
          this.clasificacionForm.solicitud_dependencia_id = this.solicitud.solicitud_dependencia_id;
        }

        if (this.solicitud.otra_dependencia) {
          this.clasificacionForm.otra_dependencia = this.solicitud.otra_dependencia;
        }
      }

      if (this.solicitud.observaciones_clasificacion) {
        this.clasificacionForm.observaciones_clasificacion = this.solicitud.observaciones_clasificacion;
      }
    }
  }

  /**
   * Carga los detalles de la solicitud
   */
  private async cargarSolicitud(solicitudId: number) {
    try {
      const response = await firstValueFrom(
        this.solicitudAsignadaHttpService.getDetallesSolicitudAsignada(solicitudId)
      );

      if (response.status && response.data) {
        this.solicitud = response.data;
      } else {
        throw new Error(response.message || 'Error al cargar la solicitud');
      }
    } catch (error) {
      console.error('Error cargando solicitud:', error);
      throw error;
    }
  }

  /**
   * Carga los catálogos de clasificación
   */
  private async cargarCatalogos() {
    this.catalogos = await this.solicitudCatalogoService.getCatalogos(false);
  }

  /**
   * Valida el formulario de clasificación
   */
  private validarFormulario(): boolean {
    this.formErrors = {};

    // Marcar todos los campos como touched al validar para el envío
    this.touchedFields = {
      ...this.touchedFields,
      solicitud_tipo_id: true,
      solicitud_tematica_id: true,
      solicitud_gobierno_nivel_id: true,
    };

    // Validar cada campo
    if (!this.clasificacionForm.solicitud_tipo_id || this.clasificacionForm.solicitud_tipo_id === 0) {
      this.formErrors.solicitud_tipo_id = undefined;
    }

    if (!this.clasificacionForm.solicitud_tematica_id || this.clasificacionForm.solicitud_tematica_id === 0) {
      this.formErrors.solicitud_tematica_id = undefined;
    } else if (this.isOtraTematica()) {
      // Si "Ninguno de los anteriores" está seleccionado, 'solicitud_tematica_otro' debe ser llenado
      this.touchedFields['solicitud_tematica_otro'] = true;
      if (!this.clasificacionForm.solicitud_tematica_otro) {
        this.formErrors.solicitud_tematica_otro = undefined;
      }
    }

    if (!this.clasificacionForm.solicitud_gobierno_nivel_id || this.clasificacionForm.solicitud_gobierno_nivel_id === 0) {
      this.formErrors.solicitud_gobierno_nivel_id = undefined;
    }

    // Validar dependencia según el nivel de gobierno
    const nivelGobierno = this.clasificacionForm.solicitud_gobierno_nivel_id;
    if (nivelGobierno) {
      this.touchedFields['solicitud_dependencia_id'] = true; // Mark as touched for UI feedback

      const nivel = this.catalogos?.niveles_gobierno.find(n => n.id === nivelGobierno)?.nombre.toLowerCase();

      if (nivel === 'federal' || nivel === 'estatal') {
        // If Federal or Estatal, a dependency must be selected
        if (!this.clasificacionForm.solicitud_dependencia_id || this.clasificacionForm.solicitud_dependencia_id === 0) {
          this.formErrors.solicitud_dependencia_id = undefined; // Mark as error
        } else if (this.isOtroDependencia()) {
          // If "Otro" is selected, 'otra_dependencia' must be filled
          this.touchedFields['otra_dependencia'] = true; // Mark as touched
          if (!this.clasificacionForm.otra_dependencia) {
            this.formErrors.otra_dependencia = undefined; // Mark as error
          }
        }
      } else if (nivel === 'municipal') {
        // If Municipal, 'otra_dependencia' must be filled
        this.touchedFields['otra_dependencia'] = true; // Mark as touched
        if (!this.clasificacionForm.otra_dependencia) {
          this.formErrors.otra_dependencia = undefined; // Mark as error
        }
      }
    }

    return Object.keys(this.formErrors).length === 0;
  }

  /**
   * Maneja el envío del formulario de clasificación
   */
  async onSubmit() {
    if (!this.solicitud || !this.validarFormulario()) {
      return;
    }

    this.saving = true;
    this.error = null;
    this.success = false;

    try {
      // Preparar los datos sin valores nulos
      const datosClasificacion: ClasificacionRequest = {
        solicitud_tipo_id: this.clasificacionForm.solicitud_tipo_id,
        solicitud_tematica_id: this.clasificacionForm.solicitud_tematica_id,
        solicitud_gobierno_nivel_id: this.clasificacionForm.solicitud_gobierno_nivel_id,
        solicitud_dependencia_id: this.clasificacionForm.solicitud_dependencia_id,
        observaciones_clasificacion: this.clasificacionForm.observaciones_clasificacion || undefined
      };

      // Incluir la temática "otra" si es necesario
      if (this.isOtraTematica()) {
        datosClasificacion.solicitud_tematica_otro = this.clasificacionForm.solicitud_tematica_otro;
      }

      // Incluir la dependencia "otra" si es necesario
      if (this.isOtroDependencia() || this.isMunicipal()) {
        datosClasificacion.otra_dependencia = this.clasificacionForm.otra_dependencia;
      }


      const response = await firstValueFrom(
        this.solicitudAsignadaHttpService.clasificarSolicitudAsignada(
          this.solicitud.id,
          datosClasificacion
        )
      );

      if (response.status) {
        this.success = true;
        // Esperar un momento y redirigir a la lista de solicitudes asignadas
        setTimeout(() => {
          this.router.navigate(['/main/solicitudes/asignadas']);
        }, 2000);
      } else {
        this.error = response.message || 'Error al clasificar la solicitud';
      }
    } catch (error) {
      console.error('Error clasificando solicitud:', error);
      this.error = 'Error de conexión al clasificar la solicitud';
    }

    this.saving = false;
  }

  /**
   * Verifica si el nivel de gobierno seleccionado es "Municipal"
   */
  isMunicipal(): boolean {
    const nivelGobierno = this.clasificacionForm.solicitud_gobierno_nivel_id;
    if (nivelGobierno && this.catalogos) {
      const nivel = this.catalogos.niveles_gobierno.find(n => n.id === nivelGobierno);
      return nivel?.nombre.toLowerCase() === 'municipal';
    }
    return false;
  }

  /**
   * Verifica si la opción "Otro" está seleccionada en dependencia
   */
  isOtroDependencia(): boolean {
    if (!this.clasificacionForm.solicitud_dependencia_id) {
      return false;
    }
    return parseInt(this.clasificacionForm.solicitud_dependencia_id.toString(), 10) === -1;
  }

  /**
   * Verifica si la opción "Ninguno de los anteriores" está seleccionada en temática
   */
  isOtraTematica(): boolean {
    if (!this.clasificacionForm.solicitud_tematica_id || this.clasificacionForm.solicitud_tematica_id === 0) {
      return false;
    }
    const tematica = this.catalogos?.tematicas.find(t => t.id === +this.clasificacionForm.solicitud_tematica_id);
    return tematica?.nombre.toLowerCase().includes('ninguno') || false;
  }

  /**
   * Cancela la clasificación y regresa a la lista de solicitudes asignadas
   */
  cancelar() {
    if (this.saving) return;
    this.router.navigate(['/main/solicitudes/asignadas']);
  }

  /**
   * Formatea una fecha para visualización
   */
  formatDate(dateString: string | Date | undefined): string {
    if (!dateString) {
      return 'No disponible';
    }
    const date = typeof dateString === 'string' ? new Date(dateString) : dateString;
    return date.toLocaleDateString('es-MX', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  /**
   * Obtiene el nombre del tipo de persona
   */
  getTipoPersonaNombre(tipo?: string): string {
    switch (tipo) {
      case 'fisica':
        return 'Persona Física';
      case 'moral':
        return 'Persona Moral';
      default:
        return 'No especificado';
    }
  }

  /**
   * Verifica si un campo tiene error
   */
  hasError(campo: keyof (ClasificacionRequest & { otra_dependencia?: string })): boolean {
    return this.touchedFields[campo] && campo in this.formErrors;
  }

  /**
   * Maneja el cambio de un campo del formulario
   */
  onFieldChange(campo: keyof (ClasificacionRequest & { otra_dependencia?: string })): void {
    // Marcar el campo como touched
    this.touchedFields[campo] = true;

    // Validar el campo específico
    const fieldValue = this.clasificacionForm[campo];

    if (!fieldValue || fieldValue === 0) {
      this.formErrors[campo] = undefined;
    } else {
      // Si el campo tiene un valor válido, remover el error
      delete this.formErrors[campo];
    }
  }

  /**
   * Obtiene el mensaje de error para un campo
   */
  getErrorMessage(campo: keyof (ClasificacionRequest & { otra_dependencia?: string })): string {
    if (this.hasError(campo)) {
      switch (campo) {
        case 'solicitud_tipo_id':
          return 'Debe seleccionar un tipo de solicitud';
        case 'solicitud_tematica_id':
          return 'Debe seleccionar un trámite';
        case 'solicitud_tematica_otro':
          return 'Debe especificar el trámite';
        case 'solicitud_gobierno_nivel_id':
          return 'Debe seleccionar un orden de gobierno';
        case 'solicitud_dependencia_id':
          return 'Debe seleccionar una dependencia';
        case 'otra_dependencia':
          return 'Debe especificar la dependencia';
        default:
          return 'Campo requerido';
      }
    }
    return '';
  }

  /**
   * Abre una evidencia en una nueva ventana para visualización
   */
  async verEvidencia(evidenciaId: number): Promise<void> {
    const exito = await this.solicitudEvidenciaService.verEvidencia(evidenciaId);
    if (!exito) {
      // Aquí podrías mostrar un mensaje de error si lo deseas
      console.error('No se pudo visualizar la evidencia');
    }
  }

  /**
   * Inicia la descarga de una evidencia
   */
  async descargarEvidencia(evidenciaId: number): Promise<void> {
    const exito = await this.solicitudEvidenciaService.descargarEvidencia(evidenciaId);
    if (!exito) {
      // Aquí podrías mostrar un mensaje de error si lo deseas
      console.error('No se pudo descargar la evidencia');
    }
  }

  /**
   * Obtiene las iniciales de un nombre
   */
  getIniciales(nombre: string): string {
    if (!nombre) return 'NA';
    return nombre
      .split(' ')
      .map(word => word.charAt(0).toUpperCase())
      .slice(0, 2)
      .join('');
  }

  /**
   * Obtiene el icono según el tipo de archivo
   */
  getFileIcon(fileName: string): string {
    const extension = fileName.toLowerCase().split('.').pop();

    switch (extension) {
      case 'pdf':
        return 'bi-file-earmark-pdf text-danger';
      case 'doc':
      case 'docx':
        return 'bi-file-earmark-word text-primary';
      case 'xls':
      case 'xlsx':
        return 'bi-file-earmark-excel text-success';
      case 'ppt':
      case 'pptx':
        return 'bi-file-earmark-slides text-warning';
      case 'jpg':
      case 'jpeg':
      case 'png':
      case 'gif':
        return 'bi-file-earmark-image text-info';
      case 'txt':
        return 'bi-file-earmark-text text-secondary';
      default:
        return 'bi-file-earmark text-muted';
    }
  }
}