import { Injectable } from "@angular/core";
import { SuperService } from "./super.service";
import { SolicitudComentario } from "../models/solicitud.comentario";

@Injectable({
    providedIn: 'root'
})
export class SolicitudComentarioService extends SuperService<SolicitudComentario> {
    protected model = 'solicitud-comentarios';

    protected override columns: (keyof SolicitudComentario)[] = [
        'id',
        'contenido',
        'solicitud_id',
        'created_by',
        'created_at',
        'updated_at',
        'deleted_at'
    ];

    /**
     * Obtiene comentarios por ID de solicitud
     *
     * @param solicitudId - ID de la solicitud
     * @param loader - Muestra loader global animado (por defecto true)
     * @returns Promise con la lista de comentarios de la solicitud
     */
    async getComentariosPorSolicitud(
        solicitudId: number,
        loader = true
    ): Promise<SolicitudComentario[]> {
        return this.all({
            conditionals: {
                solicitud_id: solicitudId,
                deleted_at: null
            },
            loader
        });
    }

    /**
     * Obtiene comentarios con relación al creador
     *
     * @param solicitudId - ID de la solicitud
     * @param loader - Muestra loader global animado (por defecto true)
     * @returns Promise con la lista de comentarios incluyendo relación con creador
     */
    async getComentariosConCreador(
        solicitudId: number,
        loader = true
    ): Promise<SolicitudComentario[]> {
        return this.all({
            conditionals: {
                solicitud_id: solicitudId,
                deleted_at: null
            },
            relations: ['creador'],
            loader
        });
    }
}