import { Component, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router, RouterModule } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { Solicitud } from '../../../models/solicitud';
import { SolicitudAccion } from '../../../models/solicitud.accion';
import { SolicitudEnProcesoOptions, SolicitudesEnProcesoService } from './services/solicitude.en.proceso.service';
import { SolicitudCatalogoService, CatalogosClasificacion } from '../../../../app/controllers/solicitud-catalogo.service';
import { PaginationInfo } from './interfaces/paginacion.interface';

@Component({
  selector: 'app-solicitudes-en-proceso',
  standalone: true,
  imports: [
    CommonModule,
    RouterModule,
    FormsModule
  ],
  templateUrl: './solicitudes-en-proceso.html',
  styleUrl: './solicitudes-en-proceso.css'
})
export class SolicitudesEnProceso implements OnInit {
  // Inyección de dependencias
  private router = inject(Router);
  private solicitudService = inject(SolicitudesEnProcesoService);
  private solicitudCatalogoService = inject(SolicitudCatalogoService); // Inyectar SolicitudCatalogoService

  // Estados del componente
  solicitudes: Solicitud[] = [];
  solicitudesFiltradas: Solicitud[] = [];
  loading = false;
  error: string | null = null;
  loadingCatalogos = false; // Nuevo: estado de carga de catálogos

  // Catálogos para filtros
  catalogos: CatalogosClasificacion = {
    tipos: [],
    tematicas: [],
    niveles_gobierno: [],
    dependenciasEstatales: [],
    dependenciasFederales: []
  };

  // Paginación
  paginacion: PaginationInfo | null = null;

  // Opciones de paginación
  opcionesPaginacion = [10, 20, 50, 100];

  // Estadísticas de actividad
  estadosActividad: {
    activas: number;
    atencion: number;
    urgentes: number;
    total: number;
  } | null = null;

  // Filtros
  filtros = {
    textoBusqueda: '',
    entidadGestionada: '',
    solicitud_tipo_id: null as number | null, // Nuevo: filtro por tipo de solicitud
    fechaInicio: '',
    fechaFin: '',
    sinActividadReciente: false,
    page: 1,
    per_page: 20,
    sort_by: 'created_at',
    sort_order: 'desc' as 'asc' | 'desc'
  };

  mostrarFiltrosAvanzados = false;

  async ngOnInit(): Promise<void> {
    await Promise.all([
      this.cargarSolicitudes(),
      this.cargarEstadosActividad(),
      this.cargarCatalogos() // Cargar catálogos
    ]);
  }

  /**
   * Cargar catálogos para filtros
   */
  async cargarCatalogos(): Promise<void> {
    this.loadingCatalogos = true;
    try {
      this.catalogos = await this.solicitudCatalogoService.getCatalogos(false);
    } catch (error) {
      console.error('Error cargando catálogos:', error);
    } finally {
      this.loadingCatalogos = false;
    }
  }

  /**
   * Carga las solicitudes en proceso con paginación y filtros
   */
  async cargarSolicitudes(): Promise<void> {
    this.loading = true;
    this.error = null;

    try {
      // Crear un objeto de parámetros limpio para la API
      const params: SolicitudEnProcesoOptions = {
        page: this.filtros.page,
        per_page: this.filtros.per_page,
        sort_by: this.filtros.sort_by,
        sort_order: this.filtros.sort_order,
      };

      // Agregar otros filtros solo si tienen un valor
      if (this.filtros.textoBusqueda) params.textoBusqueda = this.filtros.textoBusqueda;
      if (this.filtros.entidadGestionada) params.entidadGestionada = this.filtros.entidadGestionada;
      if (this.filtros.solicitud_tipo_id) params.solicitud_tipo_id = this.filtros.solicitud_tipo_id;
      if (this.filtros.fechaInicio) params.fechaInicio = this.filtros.fechaInicio;
      if (this.filtros.fechaFin) params.fechaFin = this.filtros.fechaFin;
      if (this.filtros.sinActividadReciente) params.sinActividadReciente = this.filtros.sinActividadReciente;

      const response = await this.solicitudService.getSolicitudesEnProceso(params);

      if (response.status) {
        this.solicitudes = response.data;
        this.solicitudesFiltradas = response.data;
        this.paginacion = response.pagination;
      } else {
        this.error = response.message || 'Error al cargar las solicitudes';
      }
    } catch (error: unknown) {
      this.error = 'Error de conexión al cargar las solicitudes';
      console.error('Error en solicitudes en proceso:', error);
    } finally {
      this.loading = false;
    }
  }

  /**
   * Carga las estadísticas de actividad
   */
  async cargarEstadosActividad(): Promise<void> {
    try {
      this.estadosActividad = await this.solicitudService.getEstadosActividad();
    } catch (error: unknown) {
      console.error('Error cargando estados de actividad:', error);
    }
  }

  /**
   * Aplica los filtros y recarga las solicitudes
   */
  async aplicarFiltros(): Promise<void> {
    this.filtros.page = 1;
    await this.cargarSolicitudes();
  }

  /**
   * Limpia todos los filtros
   */
  async limpiarFiltros(): Promise<void> {
    this.filtros = {
      textoBusqueda: '',
      entidadGestionada: '',
      solicitud_tipo_id: null, // Nuevo: limpiar el filtro de tipo de solicitud
      fechaInicio: '',
      fechaFin: '',
      sinActividadReciente: false,
      page: 1,
      per_page: this.filtros.per_page,
      sort_by: 'created_at',
      sort_order: 'desc'
    };
    await this.cargarSolicitudes();
  }

  /**
   * Navega a la página especificada
   */
  async cambiarPagina(pagina: number): Promise<void> {
    if (this.paginacion && pagina >= 1 && pagina <= this.paginacion.total_pages) {
      this.filtros.page = pagina;
      await this.cargarSolicitudes();
    }
  }

  /**
   * Cambia el número de elementos por página
   */
  async cambiarPerPage(perPage: number): Promise<void> {
    this.filtros.per_page = perPage;
    this.filtros.page = 1;
    await this.cargarSolicitudes();
  }

  /**
   * Cambia el ordenamiento
   */
  async cambiarOrdenamiento(campo: string): Promise<void> {
    if (this.filtros.sort_by === campo) {
      // Si ya está ordenado por este campo, invierte el orden
      this.filtros.sort_order = this.filtros.sort_order === 'asc' ? 'desc' : 'asc';
    } else {
      // Si es un campo diferente, ordena descendente por defecto
      this.filtros.sort_by = campo;
      this.filtros.sort_order = 'desc';
    }
    this.filtros.page = 1;
    await this.cargarSolicitudes();
  }

  /**
   * Obtiene el icono de ordenamiento para un campo
   */
  getIconoOrdenamiento(campo: string): string {
    if (this.filtros.sort_by !== campo) {
      return 'bi-arrow-down-up';
    }
    return this.filtros.sort_order === 'asc' ? 'bi-arrow-up' : 'bi-arrow-down';
  }

  /**
   * Obtiene el texto del rango de resultados
   */
  getTextoRangoResultados(): string {
    if (!this.paginacion) return '';

    const { from, to, total_items } = this.paginacion;
    if (total_items === 0) return 'No hay resultados';
    if (from && to) return `Mostrando ${from} a ${to} de ${total_items} solicitudes`;
    return `${total_items} solicitudes`;
  }

  /**
   * Genera array de páginas para navegación
   */
  getPaginasVisible(): number[] {
    if (!this.paginacion) return [];

    const { page, total_pages } = this.paginacion;
    const paginas: number[] = [];

    // Lógica para mostrar páginas con elipsis
    const delta = 2; // Número de páginas antes y después de la actual

    let rangoInicio = Math.max(1, page - delta);
    let rangoFin = Math.min(total_pages, page + delta);

    // Si estamos cerca del inicio, mostrar más páginas al final
    if (page <= delta + 1) {
      rangoFin = Math.min(total_pages, delta * 2 + 1);
    }

    // Si estamos cerca del final, mostrar más páginas al inicio
    if (page >= total_pages - delta) {
      rangoInicio = Math.max(1, total_pages - delta * 2);
    }

    for (let i = rangoInicio; i <= rangoFin; i++) {
      paginas.push(i);
    }

    return paginas;
  }

  /**
   * Verifica si hay filtros activos
   */
  tieneFiltrosActivos(): boolean {
    return !!(
      this.filtros.textoBusqueda ||
      this.filtros.entidadGestionada ||
      this.filtros.fechaInicio ||
      this.filtros.fechaFin ||
      this.filtros.sinActividadReciente ||
      this.filtros.solicitud_tipo_id
    );
  }

  /**
   * Navega al detalle de una solicitud
   */
  verDetalle(solicitudId: number): void {
    this.router.navigate(['/main/solicitudes/detalle', solicitudId]);
  }

  /**
   * Navega al formulario de acciones para una solicitud
   */
  gestionarAcciones(solicitudId: number): void {
    this.router.navigate(['/main/solicitudes/en-proceso/acciones', solicitudId]);
  }

  /**
   * Verifica si una solicitud tiene actividad reciente
   */
  tieneActividadReciente(solicitud: Solicitud): boolean {
    if (!solicitud.updated_at) return false;

    const sieteDiasAtras = new Date();
    sieteDiasAtras.setDate(sieteDiasAtras.getDate() - 7);

    return new Date(solicitud.updated_at) > sieteDiasAtras;
  }

  /**
   * Obtiene el color del badge según la antigüedad de la última actividad
   */
  getColorBadgeActividad(solicitud: Solicitud): string {
    if (!solicitud.updated_at) return 'text-bg-danger';

    const diasSinActividad = this.getDiasSinActividad(solicitud);

    if (diasSinActividad <= 7) return 'text-bg-success';
    if (diasSinActividad <= 15) return 'text-bg-warning';
    return 'text-bg-danger';
  }

  /**
   * Calcula los días sin actividad de una solicitud
   */
  getDiasSinActividad(solicitud: Solicitud): number {
    if (!solicitud.updated_at) return 999;

    const ultimaActividad = new Date(solicitud.acciones?.at(-1)?.created_at ?? solicitud.created_at ?? solicitud.updated_at);
    const hoy = new Date();
    const diferenciaMilisegundos = hoy.getTime() - ultimaActividad.getTime();

    return Math.floor(diferenciaMilisegundos / (1000 * 60 * 60 * 24));
  }

  /**
   * Obtiene la última acción registrada de una solicitud
   */
  getUltimaAccion(solicitud: Solicitud): SolicitudAccion | null {
    if (!solicitud.acciones || solicitud.acciones.length === 0) {
      return null;
    }

    return solicitud.acciones[0]; // Ya vienen ordenadas por fecha descendente
  }

  /**
   * Formatea una fecha para visualización
   */
  formatDate(fecha: string | Date): string {
    if (!fecha) return 'No especificada';

    const date = typeof fecha === 'string' ? new Date(fecha) : fecha;
    return date.toLocaleDateString('es-MX', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric'
    });
  }

  /**
   * Formatea una fecha con hora para visualización
   */
  formatDateTime(fecha: string | Date): string {
    if (!fecha) return 'No especificada';

    const date = typeof fecha === 'string' ? new Date(fecha) : fecha;
    return date.toLocaleDateString('es-MX', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  /**
   * Alterna la visibilidad de los filtros avanzados
   */
  toggleFiltrosAvanzados(): void {
    this.mostrarFiltrosAvanzados = !this.mostrarFiltrosAvanzados;
  }

  /**
   * Obtiene el texto descriptivo del estado de actividad
   */
  getEstadoActividadTexto(solicitud: Solicitud): string {
    const dias = this.getDiasSinActividad(solicitud);

    if (dias <= 7) return 'Activa';
    if (dias <= 15) return 'Atención';
    return 'Urgente';
  }

  /**
   * Obtiene las iniciales del nombre de una persona
   */
  getIniciales(nombre: string): string {
    if (!nombre) return 'NA';

    return nombre
      .split(' ')
      .map(palabra => palabra.charAt(0).toUpperCase())
      .join('')
      .substring(0, 2);
  }

  /**
   * Recarga la lista de solicitudes
   */
  async recargar(): Promise<void> {
    await this.cargarSolicitudes();
  }

  /**
   * Obtiene el nombre de un catálogo por su ID
   */
  getCatalogoNombre(catalogo: keyof CatalogosClasificacion, id: number | undefined): string {
    if (!id || !this.catalogos || !this.catalogos[catalogo]) {
      return 'No especificado';
    }
    const item = (this.catalogos[catalogo]).find(i => i.id === id);
    return item ? item.nombre : 'No especificado';
  }

  /**
   * Obtiene el nombre de la dependencia de una solicitud
   */
  getDependenciaNombre(solicitud: Solicitud): string {
    if (solicitud.dependencia) {
      return solicitud.dependencia.nombre;
    }
    if (solicitud.otra_dependencia) {
      return solicitud.otra_dependencia;
    }
    return 'No especificada';
  }

  /**
   * Obtiene el nombre de la temática de una solicitud con prioridad a "otra"
   */
  getTematicaNombre(solicitud: Solicitud): string {
    if (solicitud.solicitud_tematica_otro) {
      return `${solicitud.solicitud_tematica_otro} (otros)`;
    }
    if (solicitud.solicitud_tematica) {
      return solicitud.solicitud_tematica.nombre;
    }
    return this.getCatalogoNombre('tematicas', solicitud.solicitud_tematica_id ?? undefined);
  }
}