import { AfterViewInit, Component, ElementRef, inject, OnDestroy, OnInit } from '@angular/core';
import { CommonModule, DatePipe } from '@angular/common';
import { RouterLink } from '@angular/router';
import Tooltip from 'bootstrap/js/dist/tooltip';
import { SolicitudService } from '../../../controllers/solicitud.service';
import { Solicitud, SolicitudEstatus } from '../../../models/solicitud';
import { LocalStorageService } from '../../../services/localStorage/local-storage.service';
import { EstatusPipe } from '../../../pipes/estatus.pipe';

@Component({
  selector: 'app-solicitudes-list',
  imports: [CommonModule, RouterLink, EstatusPipe],
  templateUrl: './solicitudes-list.html',
  styleUrl: './solicitudes-list.css'
})
export class SolicitudesList implements OnInit, AfterViewInit, OnDestroy {
  solicitudes: Solicitud[] = [];
  SolicitudEstatus = SolicitudEstatus; // Para usar en template

  // Services
  private storage = inject(LocalStorageService);
  private solicitudesService = inject(SolicitudService);
  private elementRef = inject(ElementRef);
  private mutationObserver!: MutationObserver;

  ngOnInit(): void {
    this.fetchSolicitudes();
  }

  ngAfterViewInit(): void {
    this.initializeTooltips();
    this.mutationObserver = new MutationObserver(() => {
      this.initializeTooltips();
    });
    this.mutationObserver.observe(this.elementRef.nativeElement, {
      childList: true,
      subtree: true,
    });
  }

  ngOnDestroy(): void {
    if (this.mutationObserver) {
      this.mutationObserver.disconnect();
    }
  }

  private initializeTooltips(): void {
    const tooltipTriggerList = [].slice.call(this.elementRef.nativeElement.querySelectorAll('[data-bs-toggle="tooltip"]'));
    tooltipTriggerList.map(function (tooltipTriggerEl) {
      return new Tooltip(tooltipTriggerEl);
    });
  }

  private async fetchSolicitudes(): Promise<void> {
    this.solicitudes = await this.solicitudesService.all({
      conditionals: {
        created_by: this.storage.getUser()?.user.id ?? 0,
        deleted_at:null,
      },
      relations: [
        'evidencias',
        'acciones.creador',
        'comentarios.creador'
      ]
    });
  }

  /**
   * Formatea una fecha para mostrarla de manera amigable
   */
  formatearFecha(fecha: string | Date | null | undefined): string {
    if (!fecha) return '';
    const datePipe = new DatePipe('en-US');
    return datePipe.transform(fecha, 'dd/MM/yyyy') || '';
  }

  /**
   * Cuenta el número de evidencias adjuntas a una solicitud
   */
  contarEvidencias(solicitud: Solicitud): number {
    return solicitud.evidencias?.length || 0;
  }

  /**
   * Cuenta el número de acciones realizadas en una solicitud
   */
  contarAcciones(solicitud: Solicitud): number {
    return solicitud.acciones?.length || 0;
  }

  /**
   * Obtiene las clases CSS para el badge de estatus (sin sobreescribir colores Bootstrap)
   */
  getEstatusClass(estatus?: string): string {
    switch (estatus) {
      case SolicitudEstatus.RECIBIDA:
        return 'text-bg-secondary';
      case SolicitudEstatus.EN_PROCESO:
        return 'text-bg-warning';
      case SolicitudEstatus.RESUELTA:
        return 'text-bg-success';
      default:
        return 'text-bg-secondary';
    }
  }

  /**
   * Obtiene la descripción del estatus para el tooltip
   */
  getEstatusDescription(estatus?: string): string {
    switch (estatus) {
      case SolicitudEstatus.RECIBIDA:
        return 'Tu solicitud ha sido recibida y está pendiente de revisión.';
      case SolicitudEstatus.EN_PROCESO:
        return 'Estamos trabajando activamente en tu solicitud.';
      case SolicitudEstatus.RESUELTA:
        return 'La solicitud ha sido marcada como concluida.';
      default:
        return 'El estatus de esta solicitud no está definido.';
    }
  }

  /**
   * Obtiene el icono correspondiente al estatus
   */
  getEstatusIcon(estatus?: string): string {
    switch (estatus) {
      case SolicitudEstatus.RECIBIDA:
        return 'bi-inbox';
      case SolicitudEstatus.EN_PROCESO:
        return 'bi-hourglass-split';
      case SolicitudEstatus.RESUELTA:
        return 'bi-check-circle';
      default:
        return 'bi-question-circle';
    }
  }

  /**
   * Trunca el texto de la descripción para mostrar en la card
   */
  truncarTexto(texto: string, maxLength = 150): string {
    if (!texto) return '';
    if (texto.length <= maxLength) return texto;
    return texto.substring(0, maxLength) + '...';
  }

  /**
   * Formatea la fecha de última actualización de manera relativa
   */
  formatearFechaActualizacion(fecha: string | Date | null | undefined): string {
    if (!fecha) return '';
    const datePipe = new DatePipe('en-US');
    const hoy = new Date();
    const fechaActualizacion = new Date(fecha);
    const diasDiff = Math.floor((hoy.getTime() - fechaActualizacion.getTime()) / (1000 * 60 * 60 * 24));

    if (diasDiff === 0) {
      return 'Hoy';
    } else if (diasDiff === 1) {
      return 'Ayer';
    } else if (diasDiff < 7) {
      return `Hace ${diasDiff} días`;
    } else {
      return datePipe.transform(fecha, 'dd/MM/yyyy') || '';
    }
  }
}
