import { Injectable } from "@angular/core";
import { SuperService } from "./super.service";
import { SolicitudEvidencia } from "../models/solicitud.evidencia";
import { firstValueFrom } from "rxjs";

@Injectable({
    providedIn: 'root'
})
export class SolicitudEvidenciaService extends SuperService<SolicitudEvidencia> {
    protected model = 'solicitudes-evidencias';

    protected override columns: (keyof SolicitudEvidencia)[] = [
        'id',
        'solicitud_id',
        'nombre',
        'nombre_archivo',
        'url_archivo',
        'created_at',
        'updated_at',
        'deleted_at'
    ];

    /**
     * Descarga una evidencia usando autenticación del ApiService
     *
     * @param evidenciaId - ID de la evidencia a descargar
     * @param loader - Muestra loader global animado (por defecto true)
     * @returns Promise con la respuesta de descarga
     */
    async descargarEvidencia(evidenciaId: number, loader = true): Promise<boolean> {
        const endpoint = `api/${this.model}/${evidenciaId}/download`;
        const response = await firstValueFrom(this.api.downloadFile(endpoint, loader));

        // Crear URL de descarga y iniciar descarga
        const downloadUrl = window.URL.createObjectURL(response);
        const link = document.createElement('a');
        link.href = downloadUrl;
        link.download = `evidencia_${evidenciaId}`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        window.URL.revokeObjectURL(downloadUrl);

        return true;
    }

    /**
     * Obtiene una evidencia para visualización usando autenticación del ApiService
     *
     * @param evidenciaId - ID de la evidencia a visualizar
     * @param loader - Muestra loader global animado (por defecto true)
     * @returns Promise con la URL del archivo para visualización
     */
    async obtenerEvidenciaParaVisualizar(evidenciaId: number, loader = true): Promise<string | null> {
        const endpoint = `api/${this.model}/${evidenciaId}/view`;
        const response = await firstValueFrom(this.api.downloadFile(endpoint, loader));

        // Crear URL para visualización
        return window.URL.createObjectURL(response);
    }

    /**
     * Abre una evidencia en una nueva ventana para visualización
     *
     * @param evidenciaId - ID de la evidencia a visualizar
     * @param loader - Muestra loader global animado (por defecto true)
     * @returns Promise que resuelve a true si se pudo abrir
     */
    async verEvidencia(evidenciaId: number, loader = true): Promise<boolean> {
        const visualUrl = await this.obtenerEvidenciaParaVisualizar(evidenciaId, loader);
        if (visualUrl) {
            window.open(visualUrl, '_blank');
            return true;
        }
        return false;
    }
}