import { Component, input } from '@angular/core';
import { CommonModule } from '@angular/common';
import { TitleCasePipe, UpperCasePipe } from '@angular/common';
import { Solicitud } from '../../../../models/solicitud';

@Component({
  selector: 'app-solicitud-info',
  imports: [CommonModule, TitleCasePipe, UpperCasePipe],
  templateUrl: './solicitud-info.html'
})
export class SolicitudInfo {
  /** Solicitud a mostrar */
  solicitud = input.required<Solicitud>();

  /**
   * Formatea una fecha para visualización
   */
  formatDate(dateString: string | Date | undefined): string {
    if (!dateString) {
      return 'No disponible';
    }
    const date = typeof dateString === 'string' ? new Date(dateString) : dateString;
    return date.toLocaleDateString('es-MX', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  /**
   * Obtiene el nombre del tipo de persona
   */
  getTipoPersonaNombre(tipo?: string): string {
    switch (tipo) {
      case 'fisica':
        return 'Persona Física';
      case 'moral':
        return 'Persona Moral';
      default:
        return 'No especificado';
    }
  }

  /**
   * Obtiene las iniciales de un nombre
   */
  getIniciales(nombre: string): string {
    if (!nombre) return 'NA';
    return nombre
      .split(' ')
      .map(word => word.charAt(0).toUpperCase())
      .slice(0, 2)
      .join('');
  }
}