import { Component, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { SolicitudResueltaService } from '../shared/solicitudes-resueltas-list/services/solicitud-resuelta.service';
import { EstadisticasResponse, EstadisticasData, FiltrosEstadisticas, EstadisticaEmpresa, EstadisticaTematica } from '../shared/solicitudes-resueltas-list/interfaces/estadisticas.interface';
import { Chart, ChartType, registerables } from 'chart.js';
import { firstValueFrom } from 'rxjs';

// Registrar Chart.js
Chart.register(...registerables);

// Importar componentes de Chart.js
import {
    BarElement,
    BarController,
    CategoryScale,
    LinearScale,
    PointElement,
    LineElement,
    LineController,
    PieController,
    DoughnutController,
    ArcElement,
    Tooltip,
    Legend
} from 'chart.js';

Chart.register(
    BarController,
    LineController,
    PieController,
    DoughnutController,
    BarElement,
    LineElement,
    PointElement,
    ArcElement,
    CategoryScale,
    LinearScale,
    Tooltip,
    Legend
);

@Component({
  selector: 'app-solicitudes-resueltas-estadisticas',
  imports: [CommonModule, FormsModule],
  templateUrl: './solicitudes-resueltas-estadisticas.html',
  styleUrl: './solicitudes-resueltas-estadisticas.css'
})
export class SolicitudesResueltasEstadisticas implements OnInit {
  private solicitudesResueltaService = inject(SolicitudResueltaService);

  // Datos de estadísticas
  estadisticas: EstadisticasData | null = null;
  loading = false;
  error: string | null = null;

  // Filtros
  filtros: FiltrosEstadisticas = {
    periodo: 'mes',
    limit: 10
  };

  // Opciones de período
  periodos = [
    { value: 'dia', label: 'Diario' },
    { value: 'semana', label: 'Semanal' },
    { value: 'mes', label: 'Mensual' },
    { value: 'año', label: 'Anual' }
  ];

  // Límites para empresas
  limites = [5, 10, 15, 20];

  // Charts
  charts: Record<string, Chart> = {};

  ngOnInit(): void {
    this.cargarEstadisticas();
  }

  /**
   * Carga las estadísticas del servidor
   */
  async cargarEstadisticas(): Promise<void> {
    this.loading = true;
    this.error = null;

    try {
      const response: EstadisticasResponse = await firstValueFrom(
        this.solicitudesResueltaService.getEstadisticas(this.filtros.periodo, this.filtros.limit)
      );

      if (response.status) {
        this.estadisticas = response.data;
        // Inicializar gráficos después de un pequeño retraso para asegurar que el DOM está listo
        setTimeout(() => {
          this.inicializarCharts();
        }, 100);
      } else {
        this.error = response.message || 'Error al cargar las estadísticas';
      }
    } catch (error: unknown) {
      this.error = 'Error de conexión al cargar las estadísticas';
      console.error('Error en estadísticas:', error);
    } finally {
      this.loading = false;
    }
  }

  /**
   * Inicializa todos los gráficos después de cargar los datos
   */
  inicializarCharts(): void {
    if (!this.estadisticas) return;

    // Destruir gráficos existentes
    Object.values(this.charts).forEach(chart => chart.destroy());
    this.charts = {};

    // Crear nuevos gráficos
    this.crearGraficoFolio();
    this.crearGraficoEstatus();
    this.crearGraficoEmpresas();
    this.crearGraficoSectores();
    this.crearGraficoTematicas();
    this.crearGraficoTipos();
    this.crearGraficoOrdenGobierno();
  }

  /**
   * Cambia el período de las estadísticas
   */
  cambiarPeriodo(): void {
    this.cargarEstadisticas();
  }

  /**
   * Cambia el límite de empresas a mostrar
   */
  cambiarLimite(): void {
    this.cargarEstadisticas();
  }

  /**
   * Formatea número con separadores de miles
   */
  formatearNumero(num: number): string {
    return new Intl.NumberFormat('es-MX').format(num);
  }

  /**
   * Obtiene el total de solicitudes concluidas
   */
  getTotalResueltas(): number {
    if (!this.estadisticas?.estatus.length) return 0;
    return this.estadisticas.estatus.filter(row => row.estatus ==='RESUELTA').reduce((total, estatus) => total + (estatus.total || 0), 0);
  }

  /**
   * Obtiene la empresa con más solicitudes
   */
  getTopEmpresa(): EstadisticaEmpresa | null {
    if (!this.estadisticas?.empresa.length) return null;
    return this.estadisticas.empresa.reduce((max, empresa) =>
      (empresa.total || 0) > (max.total || 0) ? empresa : max
    );
  }

  /**
   * Obtiene el trámite más común
   */
  getTopTematica(): EstadisticaTematica | null {
    if (!this.estadisticas?.tematica.length) return null;
    return this.estadisticas.tematica.reduce((max, tematica) =>
      (tematica.total || 0) > (max.total || 0) ? tematica : max
    );
  }

  /**
   * Obtiene el color para gráficos según el índice
   */
  getColor(index: number): string {
    const colors = [
      '#0d6efd', // azul
      '#198754', // verde
      '#ffc107', // amarillo
      '#fd7e14', // naranja
      '#dc3545', // rojo
      '#6f42c1', // púrpura
      '#20c997', // cyan
      '#e83e8c', // rosa
      '#6c757d', // gris
      '#0288d1' // azul oscuro
    ];
    return colors[index % colors.length];
  }

  // Métodos para crear gráficos específicos
  crearGraficoFolio(): void {
    if (!this.estadisticas?.folio.length) return;

    const ctx = document.getElementById('chartFolio') as HTMLCanvasElement;
    if (!ctx) return;

    const data = this.estadisticas.folio;

    this.charts['folio'] = new Chart(ctx, {
      type: 'bar' as ChartType,
      data: {
        labels: data.map(item => this.formatearMes(item?.periodo)),
        datasets: [{
          label: 'Solicitudes por Período',
          data: data.map(item => item?.total || 0),
          backgroundColor: '#0d6efd',
          borderColor: '#0a58ca',
          borderWidth: 1,
          borderRadius: 4
        }]
      },
      options: {
        responsive: true,
        plugins: {
          legend: {
            display: false
          },
          tooltip: {
            callbacks: {
              label: (context) => {
                return `Solicitudes: ${context.parsed.y}`;
              }
            }
          }
        },
        scales: {
          y: {
            beginAtZero: true,
            ticks: {
              stepSize: 1
            }
          }
        }
      }
    });
  }

  crearGraficoEstatus(): void {
    if (!this.estadisticas?.estatus.length) return;

    const ctx = document.getElementById('chartEstatus') as HTMLCanvasElement;
    if (!ctx) return;

    const data = this.estadisticas.estatus;

    this.charts['estatus'] = new Chart(ctx, {
      type: 'pie' as ChartType,
      data: {
        labels: data.map(item => item?.estatus || 'Sin estatus'),
        datasets: [{
          data: data.map(item => item?.total || 0),
          backgroundColor: [
            '#198754', // verde para RESUELTA
            '#ffc107', // amarillo para otros estados
            '#fd7e14', // naranja
          ],
          borderWidth: 2,
          borderColor: '#fff'
        }]
      },
      options: {
        responsive: true,
        plugins: {
          legend: {
            position: 'bottom'
          },
          tooltip: {
            callbacks: {
              label: (context) => {
                const total = context.dataset.data.reduce((sum: number, val: unknown) => sum + (Number(val) || 0), 0);
                const percentage = ((Number(context.parsed) || 0) / total * 100).toFixed(1);
                return `${context.label}: ${context.parsed} (${percentage}%)`;
              }
            }
          }
        }
      }
    });
  }

  crearGraficoEmpresas(): void {
    if (!this.estadisticas?.empresa.length) return;

    const ctx = document.getElementById('chartEmpresas') as HTMLCanvasElement;
    if (!ctx) return;

    const data = this.estadisticas.empresa.slice(0, this.filtros.limit || 10);
    const nombresOriginales = data.map(item => item.empresa_razon_social || 'Sin nombre');

    this.charts['empresas'] = new Chart(ctx, {
      type: 'bar' as ChartType,
      data: {
        labels: data.map(item => this.truncarTexto(item.empresa_razon_social || 'Sin nombre', 30)),
        datasets: [{
          label: 'Solicitudes',
          data: data.map(item => item?.total || 0),
          backgroundColor: data.map((_, index) => this.getColor(index)),
          borderWidth: 1,
          borderRadius: 4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        indexAxis: 'y',
        plugins: {
          legend: {
            display: false
          },
          tooltip: {
            callbacks: {
              title: (context) => {
                const index = context[0]?.dataIndex;
                return `Empresa: ${nombresOriginales[index] || 'Sin nombre'}`;
              },
              label: (context) => {
                return `Solicitudes: ${context.parsed.x}`;
              }
            }
          }
        },
        scales: {
          x: {
            beginAtZero: true,
            ticks: {
              stepSize: 1
            }
          }
        }
      }
    });
  }

  crearGraficoSectores(): void {
    if (!this.estadisticas?.sector_comercial.length) return;

    const ctx = document.getElementById('chartSectores') as HTMLCanvasElement;
    if (!ctx) return;

    const data = this.estadisticas.sector_comercial.slice(0, 10);
    const nombresOriginales = data.map(item => item.sector_nombre || 'Sin nombre');

    this.charts['sectores'] = new Chart(ctx, {
      type: 'bar' as ChartType,
      data: {
        labels: data.map(item => this.formatearNombreSector(item.sector_nombre || 'Sin nombre')),
        datasets: [{
          label: 'Solicitudes',
          data: data.map(item => item?.total || 0),
          backgroundColor: data.map((_, index) => this.getColor(index)),
          borderWidth: 1,
          borderRadius: 4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            display: false
          },
          tooltip: {
            callbacks: {
              title: (context) => {
                const index = context[0]?.dataIndex;
                return `Sector: ${nombresOriginales[index] || 'Sin nombre'}`;
              },
              label: (context) => {
                return `Solicitudes: ${context.parsed.y}`;
              }
            }
          }
        },
        scales: {
          y: {
            beginAtZero: true,
            ticks: {
              stepSize: 1
            }
          },
          x: {
            ticks: {
              maxRotation: 45,
              minRotation: 0,
              autoSkip: false
            }
          }
        }
      }
    });
  }

  crearGraficoTematicas(): void {
    if (!this.estadisticas?.tematica.length) return;

    const ctx = document.getElementById('chartTematicas') as HTMLCanvasElement;
    if (!ctx) return;

    const data = this.estadisticas.tematica;

    this.charts['tematicas'] = new Chart(ctx, {
      type: 'doughnut' as ChartType,
      data: {
        labels: data.map(item => item?.tematica_nombre || 'Sin trámite'),
        datasets: [{
          data: data.map(item => item?.total || 0),
          backgroundColor: data.map((_, index) => this.getColor(index)),
          borderWidth: 2,
          borderColor: '#fff'
        }]
      },
      options: {
        responsive: true,
        plugins: {
          legend: {
            position: 'right'
          },
          tooltip: {
            callbacks: {
              label: (context) => {
                return `${context.label}: ${context.parsed}`;
              }
            }
          }
        }
      }
    });
  }

  crearGraficoTipos(): void {
    if (!this.estadisticas?.tipo_solicitud.length) return;

    const ctx = document.getElementById('chartTipos') as HTMLCanvasElement;
    if (!ctx) return;

    const data = this.estadisticas.tipo_solicitud;

    this.charts['tipos'] = new Chart(ctx, {
      type: 'pie' as ChartType,
      data: {
        labels: data.map(item => item?.tipo_nombre || 'Sin tipo'),
        datasets: [{
          data: data.map(item => item?.total || 0),
          backgroundColor: [
            '#0d6efd', // azul para Asesoría
            '#28a745', // verde para Gestión
            '#ffc107'  // amarillo para Impulso
          ],
          borderWidth: 2,
          borderColor: '#fff'
        }]
      },
      options: {
        responsive: true,
        plugins: {
          legend: {
            position: 'bottom'
          },
          tooltip: {
            callbacks: {
              label: (context) => {
                const total = context.dataset.data.reduce((sum: number, val: unknown) => sum + (Number(val) || 0), 0);
                const percentage = ((Number(context.parsed) || 0) / total * 100).toFixed(1);
                return `${context.label}: ${context.parsed} (${percentage}%)`;
              }
            }
          }
        }
      }
    });
  }

  crearGraficoOrdenGobierno(): void {
    if (!this.estadisticas?.orden_gobierno.length) return;

    const ctx = document.getElementById('chartGobierno') as HTMLCanvasElement;
    if (!ctx) return;

    const data = this.estadisticas.orden_gobierno;

    this.charts['gobierno'] = new Chart(ctx, {
      type: 'doughnut' as ChartType,
      data: {
        labels: data.map(item => item?.nivel_nombre || 'Sin nivel'),
        datasets: [{
          data: data.map(item => item?.total || 0),
          backgroundColor: [
            '#dc3545', // rojo para Federal
            '#ffc107', // amarillo para Estatal
            '#198754'  // verde para Municipal
          ],
          borderWidth: 2,
          borderColor: '#fff'
        }]
      },
      options: {
        responsive: true,
        plugins: {
          legend: {
            position: 'right'
          },
          tooltip: {
            callbacks: {
              label: (context) => {
                const total = context.dataset.data.reduce((sum: number, val: unknown) => sum + (Number(val) || 0), 0);
                const percentage = ((Number(context.parsed) || 0) / total * 100).toFixed(1);
                return `${context.label}: ${context.parsed} (${percentage}%)`;
              }
            }
          }
        }
      }
    });
  }

  /**
   * Trunca texto largo para mostrar en etiquetas
   */
  truncarTexto(texto: string, maxLength = 20): string {
    if (!texto) return '';
    if (texto.length <= maxLength) return texto;

    // Si hay espacios, truncar en la palabra más cercana
    if (texto.includes(' ')) {
      const palabras = texto.split(' ');
      let resultado = '';
      for (const palabra of palabras) {
        if (resultado.length + palabra.length + 1 <= maxLength) {
          resultado += (resultado ? ' ' : '') + palabra;
        } else {
          resultado += (resultado ? ' ' : '') + this.truncarPalabra(palabra, maxLength - resultado.length - 1);
          break;
        }
      }
      return resultado + '...';
    }

    return texto.substring(0, maxLength - 3) + '...';
  }

  /**
   * Trunca una palabra individual
   */
  truncarPalabra(palabra: string, maxLength: number): string {
    if (palabra.length <= maxLength) return palabra;
    return palabra.substring(0, maxLength - 1) + '.';
  }

  /**
   * Formatea nombre de sector para gráfica
   */
  formatearNombreSector(nombre: string): string {
    return this.truncarTexto(nombre, 25);
  }

  /**
   * Formatea fecha del período (ej: "2025-10" -> "Octubre 2025")
   */
  formatearMes(periodo: unknown): string {
    if (!periodo || typeof periodo !== 'string') {
      return String(periodo || 'N/A');
    }

    const [year, month] = periodo.split('-');
    if (!year || !month || isNaN(parseInt(month))) {
      return String(periodo);
    }

    const months = ['Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
                   'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'];
    const monthIndex = parseInt(month) - 1;

    if (monthIndex < 0 || monthIndex > 11) {
      return String(periodo);
    }

    return `${months[monthIndex]} ${year}`;
  }
}
