import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { SolicitudesResueltasEstadisticas } from "../solicitudes-resueltas-estadisticas/solicitudes-resueltas-estadisticas";
import { SolicitudesResueltasList } from "../shared/solicitudes-resueltas-list/solicitudes-resueltas-list";
import { SolicitudesResueltasReporte } from "./components/solicitudes-resueltas-reporte/solicitudes-resueltas-reporte";

@Component({
  selector: 'app-solicitudes-resueltas',
  imports: [CommonModule, SolicitudesResueltasEstadisticas, SolicitudesResueltasList, SolicitudesResueltasReporte],
  templateUrl: './solicitudes-resueltas.html',
  styleUrl: './solicitudes-resueltas.css'
})
export class SolicitudesResueltas {
  // Control de pestañas activas
  pestanaActiva: 'estadisticas' | 'lista' | 'reporte' = 'estadisticas';

  // Opciones de pestañas
  tabs = [
    {
      id: 'estadisticas' as const,
      label: 'Estadísticas',
      icono: 'bi-graph-up',
      descripcion: 'Análisis y reportes de solicitudes procesadas'
    },
    {
      id: 'lista' as const,
      label: 'Solicitudes Concluidas',
      icono: 'bi-list-check',
      descripcion: 'Listado completo de solicitudes procesadas'
    },
    {
      id: 'reporte' as const,
      label: 'Reportes',
      icono: 'bi-file-earmark-excel',
      descripcion: 'Generar y descargar reportes en Excel'
    }
  ];

  /**
   * Cambia a la pestaña especificada
   */
  cambiarPestana(pestana: 'estadisticas' | 'lista' | 'reporte'): void {
    this.pestanaActiva = pestana;
  }

  /**
   * Verifica si una pestaña está activa
   */
  isActive(pestana: 'estadisticas' | 'lista' | 'reporte'): boolean {
    return this.pestanaActiva === pestana;
  }

  /**
   * Obtiene la información de la pestaña activa
   */
  getPestanaActivaInfo() {
    return this.tabs.find(p => p.id === this.pestanaActiva);
  }
}
