import { Component, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router, ActivatedRoute, RouterModule } from '@angular/router';
import { FormsModule, ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { SolicitudService } from '../../../controllers/solicitud.service';
import { SolicitudAccionService } from '../../../controllers/solicitud-accion.service';
import { Solicitud } from '../../../models/solicitud';
import { SolicitudAccion } from '../../../models/solicitud.accion';
import { VanillaDialogService } from '../../../services/vanilla-dialog/vanilla-dialog.service';
import { LoaderService } from '../../../services/loader/loader.service';
import { SolicitudInfo } from "../shared/solicitud-info/solicitud-info.component";
import { SolicitudDocumentos } from "../shared/solicitud-documentos/solicitud-documentos.component";
import { ComentariosBox } from "../shared/comentarios-box/comentarios-box";
import { SolicitudHistorialAcciones } from "../shared/solicitud-historial-acciones/solicitud-historial-acciones.component";
import { SolicitudCatalogoService } from '../../../controllers/solicitud-catalogo.service';
import { SolicitudDependencia } from '../../../models/solicitud.dependencia';

@Component({
  selector: 'app-solicitud-acciones',
  standalone: true,
  imports: [
    CommonModule,
    RouterModule,
    FormsModule,
    ReactiveFormsModule,
    SolicitudInfo,
    SolicitudDocumentos,
    ComentariosBox,
    SolicitudHistorialAcciones
  ],
  templateUrl: './solicitud-acciones.html',
  styleUrl: './solicitud-acciones.css'
})
export class SolicitudAcciones implements OnInit {
  // Inyección de dependencias
  private router = inject(Router);
  private activatedRoute = inject(ActivatedRoute);
  private formBuilder = inject(FormBuilder);
  private solicitudService = inject(SolicitudService);
  private solicitudAccionService = inject(SolicitudAccionService);
  private dialogService = inject(VanillaDialogService);
  private loaderService = inject(LoaderService);
  private solicitudCatalogoService = inject(SolicitudCatalogoService);

  // Estados del componente
  solicitud: Solicitud | null = null;
  acciones: SolicitudAccion[] = [];
  loading = false;
  saving = false;
  error: string | null = null;
  success = false;

  // Dependencias gestionadas
  dependenciasGestionadas: SolicitudDependencia[] = [];

  // Formulario para nueva acción
  accionForm!: FormGroup;

  constructor() {
    this.inicializarFormulario();
  }

  async ngOnInit(): Promise<void> {
    const solicitudId = Number(this.activatedRoute.snapshot.paramMap.get('id'));
    if (solicitudId) {
      await this.cargarDatosSolicitud(solicitudId);
    } else {
      this.error = 'No se proporcionó un ID de solicitud válido';
    }
  }

  /**
   * Inicializa el formulario de acción
   */
  private inicializarFormulario(): void {
    this.accionForm = this.formBuilder.group({
      dependencia_gestionada_id: [0],
      otra_dependencia_gestionada: [''],
      descripcion: ['', [Validators.required, Validators.minLength(10), Validators.maxLength(1000)]],
      fecha_inicio: ['', [Validators.required]],
      fecha_fin: ['', [Validators.required]],
      resuelve_solicitud: [false, [Validators.required]],
      comentarios_resolucion: ['', [Validators.maxLength(500)]]
    });

    // Escuchar cambios en el checkbox de resolución
    this.accionForm.get('resuelve_solicitud')?.valueChanges.subscribe(value => {
      const comentariosControl = this.accionForm.get('comentarios_resolucion');
      if (value) {
        comentariosControl?.setValidators([Validators.required, Validators.maxLength(500)]);
      } else {
        comentariosControl?.clearValidators();
      }
      comentariosControl?.updateValueAndValidity();
    });

    // Escuchar cambios en el select de dependencia gestionada
    this.accionForm.get('dependencia_gestionada_id')?.valueChanges.subscribe(() => {
      this.updateOtraDependenciaValidation();
    });
  }

  /**
   * Actualiza dinámicamente la validación del campo otra_dependencia_gestionada
   */
  private updateOtraDependenciaValidation(): void {
    const otraDepControl = this.accionForm.get('otra_dependencia_gestionada');
    const depId = this.accionForm.get('dependencia_gestionada_id')?.value;
    const isMunicipal = this.isMunicipal();
    const isOtro = parseInt(depId?.toString() || '0', 10) === -1;

    // El campo es requerido solo si es municipal o se seleccionó "Otro"
    if (isMunicipal || isOtro) {
      otraDepControl?.setValidators([Validators.required]);
    } else {
      otraDepControl?.clearValidators();
    }
    otraDepControl?.updateValueAndValidity();
  }

  /**
   * Carga los datos de la solicitud y sus acciones
   */
  async cargarDatosSolicitud(solicitudId: number): Promise<void> {
    this.loading = true;
    this.error = null;

    try {
      // Cargar solicitud y catálogos en paralelo
      const [solicitudData, dependenciasFederales, dependenciasEstatales] = await Promise.all([
        this.solicitudService.find(solicitudId, ['evidencias', 'comentarios.creador', 'acciones.creador', 'solicitudGobiernoNivel']),
        this.solicitudCatalogoService.getSolicitudDependenciaFederal(false),
        this.solicitudCatalogoService.getSolicitudDependenciaEstatal(false)
      ]);

      this.solicitud = solicitudData || null;

      if (!this.solicitud) {
        this.error = 'No se encontró la solicitud';
        return;
      }

      // Verificar que esté en proceso
      if (this.solicitud.estatus !== 'EN PROCESO') {
        this.error = `Esta solicitud tiene estatus "${this.solicitud.estatus}" y no puede recibir acciones`;
        return;
      }

      // Filtrar dependencias según el nivel de gobierno de la clasificación
      this.filtrarDependenciasPorNivelGobierno(dependenciasFederales, dependenciasEstatales);

      // Actualizar validación del campo otra_dependencia_gestionada
      this.updateOtraDependenciaValidation();

      // Cargar acciones existentes
      this.acciones = await this.solicitudAccionService.getAccionesBySolicitudId(solicitudId);

    } catch (error) {
      console.error('Error al cargar datos de la solicitud:', error);
      this.error = 'No se pudieron cargar los datos de la solicitud. Por favor, intente nuevamente.';
    } finally {
      this.loading = false;
    }
  }

  /**
   * Filtra las dependencias según el nivel de gobierno asignado en la clasificación
   */
  private filtrarDependenciasPorNivelGobierno(federales: SolicitudDependencia[], estatales: SolicitudDependencia[]): void {
    if (!this.solicitud?.solicitud_gobierno_nivel_id) {
      // Si no hay clasificación, mostrar todas
      this.dependenciasGestionadas = [];
      return;
    }

    // Obtener el nombre del nivel de gobierno
    const nivelNombre = this.solicitud.solicitud_gobierno_nivel?.nombre.toLowerCase();

    if (nivelNombre?.includes('federal')) {
      this.dependenciasGestionadas = federales;
    } else if (nivelNombre?.includes('estatal')) {
      this.dependenciasGestionadas = estatales;
    } else {
      // Por defecto, mostrar todas
      this.dependenciasGestionadas = [];
    }
  }

  /**
   * Envía el formulario para registrar una nueva acción
   */
  async onSubmit(): Promise<void> {
    if (this.accionForm.invalid) {
      this.markAllAsTouched();
      return;
    }

    this.saving = true;

    try {
      const formData = this.accionForm.value;

      // Validar que fecha_fin sea posterior o igual a fecha_inicio
      if (formData.fecha_fin < formData.fecha_inicio) {
        this.dialogService.show({
          title: 'Error de validación',
          body: 'La fecha de fin debe ser posterior o igual a la fecha de inicio.',
          tipo: 'danger'
        });
        this.saving = false;
        return;
      }

      // Crear la acción
      // Determinar el valor de entidad_gestionada
      let entidadGestionadaValor: string;
      if (this.isMunicipal()) {
        // Para municipal, siempre usar el campo de texto
        entidadGestionadaValor = formData.otra_dependencia_gestionada;
      } else if (formData.dependencia_gestionada_id == -1) {
        // Si seleccionó "Otro", usar el campo de texto
        entidadGestionadaValor = formData.otra_dependencia_gestionada;
      } else if (formData.dependencia_gestionada_id > 0) {
        // Si seleccionó una dependencia del catálogo
        const dep = this.dependenciasGestionadas.find(d => d.id == formData.dependencia_gestionada_id);
        entidadGestionadaValor = dep!.nombre
      } else {
        throw new Error("No dependencia encontrada", formData);
      }

      const nuevaAccion: Partial<SolicitudAccion> = {
        solicitud_id: this.solicitud!.id,
        entidad_gestionada: entidadGestionadaValor,
        descripcion: formData.descripcion,
        fecha_inicio: new Date(formData.fecha_inicio),
        fecha_fin: new Date(formData.fecha_fin),
        resuelve_solicitud: formData.resuelve_solicitud,
        comentarios_resolucion: formData.resuelve_solicitud ? formData.comentarios_resolucion : null
      };

      const accionCreada = await this.solicitudAccionService.crearAccion(nuevaAccion);

      if (!accionCreada) {
        throw new Error('No se pudo crear la acción');
      }

      // Si la acción resuelve la solicitud, cambiar el estatus
      if (formData.resuelve_solicitud) {
        await this.solicitudService.marcarComoResuelta(this.solicitud!.id);

        // Mostrar mensaje de éxito con información de notificación
        this.dialogService.show({
          title: '¡Solicitud Resuelta!',
          body: `La solicitud #${this.solicitud!.id.toString().padStart(6, '0')} ha sido marcada como resuelta y se enviará una notificación al correo del solicitante.`,
          tipo: 'success'
        });
      } else {
        // Mostrar mensaje de acción registrada
        this.dialogService.show({
          title: 'Acción Registrada',
          body: 'La acción ha sido registrada exitosamente.',
          tipo: 'success'
        });
      }

      // Recargar datos
      await this.cargarDatosSolicitud(this.solicitud!.id);

      // Limpiar formulario si no resolvió la solicitud
      if (!formData.resuelve_solicitud) {
        this.resetFormulario();
      } else {
        this.success = true;
      }

    } catch (error) {
      console.error('Error al registrar acción:', error);
      this.dialogService.show({
        title: 'Error',
        body: 'No se pudo registrar la acción. Por favor, intente nuevamente.',
        tipo: 'danger'
      });
    } finally {
      this.saving = false;
    }
  }

  /**
   * Resetea el formulario para una nueva acción
   */
  resetFormulario(): void {
    this.accionForm.reset({
      dependencia_gestionada_id: 0,
      otra_dependencia_gestionada: '',
      descripcion: '',
      fecha_inicio: new Date().toISOString().split('T')[0],
      fecha_fin: '',
      resuelve_solicitud: false,
      comentarios_resolucion: ''
    });
  }

  /**
   * Cancela y vuelve a la lista de solicitudes en proceso
   */
  cancelar(): void {
    this.router.navigate(['/main/solicitudes/en-proceso']);
  }

  /**
   * Navega al detalle de la solicitud
   */
  verDetalle(): void {
    if (this.solicitud) {
      this.router.navigate(['/main/solicitudes/detalle', this.solicitud.id]);
    }
  }

  /**
   * Verifica si un campo tiene errores
   */
  hasError(campo: string): boolean {
    const control = this.accionForm.get(campo);
    return control ? control.invalid && (control.dirty || control.touched) : false;
  }

  /**
   * Marca todos los campos como touched para mostrar errores
   */
  markAllAsTouched(): void {
    Object.keys(this.accionForm.controls).forEach(key => {
      this.accionForm.get(key)?.markAsTouched();
    });
  }

  /**
   * Verifica si el nivel de gobierno es Municipal
   */
  isMunicipal(): boolean {
    const nivelNombre = this.solicitud?.solicitud_gobierno_nivel?.nombre.toLowerCase();
    return nivelNombre?.includes('municipal') || false;
  }

  /**
   * Verifica si la opción "Otro" está seleccionada
   */
  isOtroDependenciaGestionada(): boolean {
    const id = this.accionForm.get('dependencia_gestionada_id')?.value;
    return parseInt(id?.toString() || '0', 10) === -1;
  }

  /**
   * Maneja el cambio en el select de dependencia
   */
  onDependenciaGestionadaChange(): void {
    const id = this.accionForm.get('dependencia_gestionada_id')?.value;
    const isOtro = parseInt(id?.toString() || '0', 10) === -1;

    if (!isOtro) {
      // Si no es "Otro", limpiar el campo de texto
      this.accionForm.patchValue({ otra_dependencia_gestionada: '' });
    }
  }

  /**
   * Obtiene el mensaje de error para un campo
   */
  getErrorMessage(campo: string): string {
    const control = this.accionForm.get(campo);
    if (!control || !control.errors) return '';

    const errors = control.errors;

    if (errors['required']) {
      if (campo === 'dependencia_gestionada_id') {
        return 'Debe seleccionar una dependencia gestionada';
      }
      if (campo === 'otra_dependencia_gestionada') {
        return 'Debe especificar el nombre de la dependencia';
      }
      return 'Este campo es obligatorio';
    }
    if (errors['minlength']) return `Mínimo ${errors['minlength'].requiredLength} caracteres`;
    if (errors['maxlength']) return `Máximo ${errors['maxlength'].requiredLength} caracteres`;
    if (errors['email']) return 'Formato de correo inválido';
    if (errors['pattern']) return 'Formato inválido';

    return 'Error de validación';
  }

  /**
   * Formatea una fecha para visualización
   */
  formatDate(fecha: string | Date): string {
    if (!fecha) return 'No especificada';

    const date = typeof fecha === 'string' ? new Date(fecha) : fecha;
    return date.toLocaleDateString('es-MX', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric'
    });
  }

  /**
   * Formatea una fecha con hora para visualización
   */
  formatDateTime(fecha: string | Date): string {
    if (!fecha) return 'No especificada';

    const date = typeof fecha === 'string' ? new Date(fecha) : fecha;
    return date.toLocaleDateString('es-MX', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  /**
   * Obtiene las iniciales del nombre de una persona
   */
  getIniciales(nombre: string): string {
    if (!nombre) return 'NA';

    return nombre
      .split(' ')
      .map(palabra => palabra.charAt(0).toUpperCase())
      .join('')
      .substring(0, 2);
  }

  /**
   * Vuelve a la lista de solicitudes en proceso
   */
  volverALista(): void {
    this.router.navigate(['/main/solicitudes/en-proceso']);
  }
}