import { Component, inject, input, output } from '@angular/core';
import { CommonModule, DatePipe } from '@angular/common';
import { SolicitudEvidencia } from '../../../../models/solicitud.evidencia';
import { SolicitudEvidenciaService } from '../../../../controllers/solicitud-evidencia.service';
import { LocalStorageService } from '../../../../services/localStorage/local-storage.service';
import { Solicitud } from '../../../../models/solicitud';
import { SolicitudService } from '../../../../controllers/solicitud.service';

@Component({
  selector: 'app-solicitud-documentos',
  imports: [
    CommonModule,
  ],
  templateUrl: './solicitud-documentos.html'
})
export class SolicitudDocumentos {
  public storage = inject(LocalStorageService)

  /** ID de la solicitud para descargar/ver documentos */
  solicitud = input.required<Solicitud>();

  /** Evento que se emite cuando se actualiza la lista de documentos */
  documentosActualizados = output<void>();

  /** Estado de carga para operaciones individuales */
  loadingStates: Record<number, boolean> = {};

  selectedFiles: File[] = [];

  error: string | null = null;

  // Upload de archivos
  uploadingFiles = false;

  private solicitudService = inject(SolicitudService)
  private solicitudEvidenciaService = inject(SolicitudEvidenciaService);

  /**
 * Maneja la selección de archivos para subir
 */
  onFileSelect(event: Event): void {
    const input = event.target as HTMLInputElement;
    if (input.files && input.files.length > 0) {
      this.selectedFiles = Array.from(input.files);
    }
  }

  /**
   * Sube archivos adicionales a la solicitud
   */
  async subirArchivos() {
    if (!this.solicitud || this.selectedFiles.length === 0) {
      return;
    }

    this.uploadingFiles = true;

    try {
      await this.solicitudService.actualizarSolicitud(
        this.solicitud().id,
        {}, // No se actualizan datos de la solicitud
        this.selectedFiles,
        false
      );

      this.documentosActualizados.emit()

      // Limpiar selección
      this.selectedFiles = [];

      // Limpiar input de archivos
      const fileInput = document.getElementById('fileInput') as HTMLInputElement;
      if (fileInput) {
        fileInput.value = '';
      }
    } catch (error) {
      console.error('Error al subir archivos:', error);
      this.error = 'Error al subir los archivos';
    } finally {
      this.uploadingFiles = false;
    }
  }

  /**
   * Inicia la descarga de un documento
   */
  async descargarDocumento(documento: SolicitudEvidencia): Promise<void> {
    if (this.loadingStates[documento.id]) {
      return;
    }

    this.loadingStates[documento.id] = true;

    try {
      const exito = await this.solicitudEvidenciaService.descargarEvidencia(documento.id);
      if (typeof exito !== 'boolean' || !exito) {
        console.error('No se pudo descargar el documento');
      }
    } catch (error) {
      console.error('Error descargando documento:', error);
    } finally {
      this.loadingStates[documento.id] = false;
    }
  }

  /**
   * Abre un documento en una nueva ventana para visualización
   */
  async verDocumento(documento: SolicitudEvidencia): Promise<void> {
    if (this.loadingStates[documento.id]) {
      return;
    }

    this.loadingStates[documento.id] = true;

    try {
      const exito = await this.solicitudEvidenciaService.verEvidencia(documento.id);
      if (typeof exito !== 'boolean' && !exito) {
        console.error('No se pudo visualizar el documento');
      }
    } catch (error) {
      console.error('Error visualizando documento:', error);
    } finally {
      this.loadingStates[documento.id] = false;
    }
  }

  /**
 * Formatea una fecha para visualización
 */
  formatDate(dateString: string | Date | undefined): string {
    if (!dateString) {
      return 'No disponible';
    }
    const datePipe = new DatePipe('en-US');
    return datePipe.transform(dateString, 'dd/MM/yyyy HH:mm') || 'No disponible';
  }


  /**
   * Obtiene el icono según el tipo de archivo
   */
  getFileIcon(fileName: string): string {
    const extension = fileName.toLowerCase().split('.').pop();

    switch (extension) {
      case 'pdf':
        return 'bi-file-earmark-pdf text-danger';
      case 'doc':
      case 'docx':
        return 'bi-file-earmark-word text-primary';
      case 'xls':
      case 'xlsx':
        return 'bi-file-earmark-excel text-success';
      case 'ppt':
      case 'pptx':
        return 'bi-file-earmark-slides text-warning';
      case 'jpg':
      case 'jpeg':
      case 'png':
      case 'gif':
        return 'bi-file-earmark-image text-info';
      case 'txt':
        return 'bi-file-earmark-text text-secondary';
      default:
        return 'bi-file-earmark text-muted';
    }
  }

  /**
   * Formatea el tamaño del archivo para visualización
   */
  formatFileSize(bytes?: number): string {
    if (!bytes) return 'Tamaño no disponible';

    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(1024));

    if (i === 0) return `${bytes} ${sizes[i]}`;

    return `${(bytes / Math.pow(1024, i)).toFixed(1)} ${sizes[i]}`;
  }

  /**
   * Verifica si un documento está siendo procesado
   */
  isLoading(documentoId: number): boolean {
    return this.loadingStates[documentoId] || false;
  }

  get esUsuarioCreador() {
    return this.solicitud()?.created_by === this.storage.getUser()?.user.id
  }
}