import { Component, Input, OnInit, OnChanges, SimpleChanges, output, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { SolicitudResueltaService, FiltrosSolicitudesResueltas, SolicitudesResueltasResponse, SolicitudResueltaData } from './services/solicitud-resuelta.service';
import { PaginadorComponent } from '../../../../shared/paginador/paginador.component';
import { SolicitudCatalogoService, CatalogosClasificacion } from '../../../../controllers/solicitud-catalogo.service';
import { firstValueFrom } from 'rxjs';
import { Router } from '@angular/router';
import { LocalStorageService } from '../../../../services/localStorage/local-storage.service';

@Component({
  selector: 'app-solicitudes-resueltas-list',
  imports: [CommonModule, FormsModule, PaginadorComponent],
  templateUrl: './solicitudes-resueltas-list.html',
  styleUrl: './solicitudes-resueltas-list.css'
})
export class SolicitudesResueltasList implements OnInit, OnChanges {
  @Input() showFilters = true;
  @Input() initialFilters?: FiltrosSolicitudesResueltas;

  // Output para emitir eventos
  solicitudClick = output<SolicitudResueltaData>();
  filterChange = output<FiltrosSolicitudesResueltas | undefined>();

  private solicitudResueltaService = new SolicitudResueltaService();
  private catalogoService = new SolicitudCatalogoService();

  // Datos de solicitudes
  solicitudes: SolicitudResueltaData[] = [];
  loading = false;
  error: string | null = null;

  // Paginación
  paginador = { page: 1, per_page: 12 };
  itemsPerPage = 12;
  totalItems = 0;
  totalPages = 0;

  // Filtros
  filtros: FiltrosSolicitudesResueltas = {
    folio: undefined,
    rfc: '',
    empresa: '',
    tematica_id: undefined,
    gobierno_nivel_id: undefined,
    tipo_id: undefined,
    fecha_inicio: '',
    fecha_fin: ''
  };

  // Control de visibilidad de filtros
  showFiltersPanel = false;
  showAdvancedFilters = false;

  // Catálogos para filtros
  catalogos: CatalogosClasificacion | null = null;
  loadingCatalogos = false;

  private router = inject(Router)
  private storage = inject(LocalStorageService)

  ngOnInit(): void {
    if (this.initialFilters) {
      this.filtros = { ...this.filtros, ...this.initialFilters };
    }
    this.cargarCatalogos();
    this.cargarSolicitudes();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['initialFilters'] && changes['initialFilters'].currentValue) {
      this.filtros = { ...this.filtros, ...changes['initialFilters'].currentValue };
      this.cargarSolicitudes();
    }
  }

  /**
   * Carga los catálogos para los filtros
   */
  async cargarCatalogos(): Promise<void> {
    this.loadingCatalogos = true;

    try {
      // Usar el servicio de catálogos que carga todo en una sola llamada
      this.catalogos = await this.catalogoService.getCatalogos(false);
    } catch (error: unknown) {
      console.error('Error al cargar catálogos:', error);
      this.catalogos = null;
    } finally {
      this.loadingCatalogos = false;
    }
  }

  /**
   * Carga las solicitudes concluidas según filtros y paginación
   */
  async cargarSolicitudes(): Promise<void> {
    this.loading = true;
    this.error = null;

    try {
      const filtrosConPaginacion = {
        ...this.limpiarFiltros(),
        page: this.paginador.page,
        per_page: this.paginador.per_page
      };

      const response: SolicitudesResueltasResponse = await firstValueFrom(
        this.solicitudResueltaService.getSolicitudesResueltas(filtrosConPaginacion)
      );

      this.solicitudes = response.data || [];
      this.totalItems = response.total_items;
      this.totalPages = response.total_pages;
      this.paginador.page = response.page;

      if (!response.status) {
        this.error = response.message || 'Error al cargar las solicitudes';
      }
    } catch (error: unknown) {
      this.error = (error as Error).message || 'Error de conexión al cargar las solicitudes';
      this.solicitudes = [];
    } finally {
      this.loading = false;
    }
  }

  /**
   * Limpia los filtros vacíos para enviar solo los valores válidos
   */
  private limpiarFiltros(): FiltrosSolicitudesResueltas | undefined {
    const filtrosLimpios: Record<string, string | number | undefined> = {};

    Object.keys(this.filtros).forEach(key => {
      const value = this.filtros[key as keyof FiltrosSolicitudesResueltas];
      if (value !== undefined && value !== null && value !== '') {
        filtrosLimpios[key] = value;
      }
    });

    return Object.keys(filtrosLimpios).length > 0 ? filtrosLimpios : undefined;
  }

  /**
   * Maneja el cambio de página
   */
  onPaginaChange(pagina: number): void {
    this.paginador.page = pagina;
    this.cargarSolicitudes();
  }

  /**
   * Aplica los filtros y recarga los datos
   */
  aplicarFiltros(): void {
    this.paginador.page = 1;
    this.cargarSolicitudes();
    this.filterChange.emit(this.limpiarFiltros());
  }

  /**
   * Limpia todos los filtros
   */
  limpiarFiltrosForm(): void {
    this.filtros = {
      folio: undefined,
      rfc: '',
      empresa: '',
      tematica_id: undefined,
      gobierno_nivel_id: undefined,
      tipo_id: undefined,
      fecha_inicio: '',
      fecha_fin: ''
    };
    this.paginador.page = 1;
    this.cargarSolicitudes();
    this.filterChange.emit(undefined);
  }

  /**
   * Formatea fecha para mostrar en la vista
   */
  formatearFecha(fecha: string | Date | undefined): string {
    if (!fecha) return 'N/A';

    const date = typeof fecha === 'string' ? new Date(fecha) : fecha;
    return date.toLocaleDateString('es-MX', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric'
    });
  }

  /**
   * Formatea fecha relativa (hace cuanto tiempo)
   */
  formatearFechaActualizacion(fecha: string | Date | undefined): string {
    if (!fecha) return 'N/A';

    const date = typeof fecha === 'string' ? new Date(fecha) : fecha;
    const now = new Date();
    const diffTime = Math.abs(now.getTime() - date.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays === 0) {
      const diffHours = Math.floor(diffTime / (1000 * 60 * 60));
      if (diffHours === 0) {
        const diffMinutes = Math.floor(diffTime / (1000 * 60));
        return diffMinutes <= 1 ? 'Ahora' : `Hace ${diffMinutes} min`;
      }
      return `Hace ${diffHours} h`;
    } else if (diffDays === 1) {
      return 'Ayer';
    } else if (diffDays < 7) {
      return `Hace ${diffDays} días`;
    } else {
      return this.formatearFecha(fecha);
    }
  }

  /**
   * Trunca texto a una longitud máxima
   */
  truncarTexto(texto: string, maxLength = 100): string {
    if (!texto) return '';
    return texto.length > maxLength ? texto.substring(0, maxLength) + '...' : texto;
  }

  /**
   * Obtiene clase CSS según el estatus
   */
  getEstatusClass(estatus?: string): string {
    if (!estatus) return 'bg-secondary';

    switch (estatus.toUpperCase()) {
      case 'RESUELTA':
        return 'bg-success';
      case 'EN PROCESO':
        return 'bg-warning';
      case 'RECIBIDA':
        return 'bg-info';
      default:
        return 'bg-secondary';
    }
  }

  /**
   * Obtiene ícono según el estatus
   */
  getEstatusIcon(estatus?: string): string {
    if (!estatus) return 'bi-question-circle';

    switch (estatus.toUpperCase()) {
      case 'RESUELTA':
        return 'bi-check-circle';
      case 'EN PROCESO':
        return 'bi-clock';
      case 'RECIBIDA':
        return 'bi-inbox';
      default:
        return 'bi-question-circle';
    }
  }

  /**
   * Alterna la visibilidad del panel de filtros
   */
  toggleFilters(): void {
    this.showFiltersPanel = !this.showFiltersPanel;
  }

  /**
   * Maneja el clic en una solicitud
   */
  onSolicitudSeleccionada(solicitud: SolicitudResueltaData): void {
    this.router.navigate(['/main/solicitudes/detalle', solicitud.id]);
  }

  /**
   * Obtiene el título según el tipo de usuario
   */
  getTitulo(): string {
    const role = this.storage.getRolUser()
    switch (role) {
      case 'admin-sistema':
        return 'Solicitudes Concluidas - Administración';
      case 'admin-general':
        return 'Solicitudes Concluidas - Administración';
      case 'usuario-sei':
        return 'Mis Solicitudes Concluidas';
      default:
        return 'Solicitudes Concluidas';
    }
  }

  /**
   * Obtiene descripción según el tipo de usuario
   */
  getDescripcion(): string {
    const role = this.storage.getRolUser()
    switch (role) {
      case 'admin-sistema':
        return 'Consulta todas las solicitudes que han sido concluidas en el sistema';
      case 'admin-general':
        return 'Consulta todas las solicitudes que han sido concluidas en el sistema';
      case 'usuario-sei':
        return 'Consulta las solicitudes que te han sido asignadas y han sido concluidas';
      default:
        return 'Lista de solicitudes concluidas';
    }
  }

  /**
   * Verifica si hay filtros activos
   */
  tieneFiltrosActivos(): boolean {
    return Object.keys(this.limpiarFiltros() || {}).length > 0;
  }

  /**
   * Cuenta cuántos filtros están activos
   */
  contarFiltrosActivos(): number {
    const filtrosLimpios = this.limpiarFiltros();
    return filtrosLimpios ? Object.keys(filtrosLimpios).length : 0;
  }
}
