import { Injectable } from '@angular/core';
import { SuperService, Conditional } from './super.service';
import { SolicitudAccion } from '../models/solicitud.accion';

@Injectable({
  providedIn: 'root'
})
export class SolicitudAccionService extends SuperService<SolicitudAccion> {
  protected override model = 'solicitud-acciones';
  protected override columns: (keyof SolicitudAccion)[] = [
    'fecha_inicio',
    'fecha_fin',
    'entidad_gestionada',
    'descripcion',
    'solicitud_id',
    'resuelve_solicitud',
    'comentarios_resolucion'
  ];

  /**
   * Obtiene todas las acciones de una solicitud específica
   */
  async getAccionesBySolicitudId(solicitudId: number): Promise<SolicitudAccion[]> {
    const conditionals: Conditional[] = [
      { key: 'solicitud_id', operator: '=', value: solicitudId }
    ];

    return this.all({
      conditionals,
      relations: ['creador'],
      sort: { column: 'created_at', desc: true } 
    });
  }

  /**
   * Obtiene las acciones más recientes de una solicitud
   */
  async getUltimasAcciones(solicitudId: number, limite = 5): Promise<SolicitudAccion[]> {
    const conditionals: Conditional[] = [
      { key: 'solicitud_id', operator: '=', value: solicitudId }
    ];

    return this.all({
      conditionals,
      relations: ['creador'],
      extraData: {
        sort: { column: 'created_at', desc: true },
        limit: limite
      }
    });
  }

  /**
   * Crea una nueva acción para una solicitud
   */
  async crearAccion(accion: Partial<SolicitudAccion>): Promise<SolicitudAccion | null> {
    return await this.new(accion) || null;
  }

  /**
   * Actualiza una acción existente
   */
  async actualizarAccion(id: number, accion: Partial<SolicitudAccion>): Promise<SolicitudAccion | null> {
    const resultado = await this.update(id, accion);
    return resultado.status ? accion as SolicitudAccion : null;
  }

  /**
   * Elimina una acción (usando switch para soft delete)
   */
  async eliminarAccion(id: number): Promise<boolean> {
    try {
      return await this.switch(id);
    } catch (error) {
      console.error('Error al eliminar acción:', error);
      return false;
    }
  }

  /**
   * Busca acciones por entidad gestionada
   */
  async buscarPorEntidad(entidad: string): Promise<SolicitudAccion[]> {
    const conditionals: Conditional[] = [
      { key: 'entidad_gestionada', operator: 'LIKE', value: `%${entidad}%` }
    ];

    return this.all({
      conditionals,
      relations: ['creador', 'solicitud']
    });
  }

  /**
   * Obtiene acciones en un rango de fechas
   */
  async getAccionesPorRangoFechas(fechaInicio: Date, fechaFin: Date): Promise<SolicitudAccion[]> {
    const conditionals: Conditional[] = [
      {
        key: 'fecha_inicio',
        operator: 'BETWEEN',
        value: `${fechaInicio.toISOString()},${fechaFin.toISOString()}`
      }
    ];

    return this.all({
      conditionals,
      relations: ['creador', 'solicitud']
    });
  }

  /**
   * Verifica si una solicitud tiene acciones recientes (últimos 7 días)
   */
  async tieneAccionesRecientes(solicitudId: number): Promise<boolean> {
    const haceSieteDias = new Date();
    haceSieteDias.setDate(haceSieteDias.getDate() - 7);

    const conditionals: Conditional[] = [
      { key: 'solicitud_id', operator: '=', value: solicitudId },
      { key: 'created_at', operator: '>=', value: haceSieteDias.toISOString() }
    ];

    const acciones = await this.all({
      conditionals,
      relations: ['creador']
    });

    return acciones.length > 0;
  }
}