import { Injectable } from "@angular/core";
import { SuperService } from "./super.service";
import { Solicitud, ClasificacionRequest, CatalogosClasificacion } from "../models/solicitud";
import { firstValueFrom } from "rxjs";
import { StandarResponse } from "../services/api/api-service.service";

/**
 * Interfaz para estadísticas de solicitudes asignadas al usuario
 */
interface EstadisticasSolicitudesAsignadas {
    total_asignadas: number;
    asignaciones_activas: number;
    completadas: number;
    por_clasificar: number;
    por_tipo: { nombre: string; total: number }[];
    por_tematica: { nombre: string; total: number }[];
}

@Injectable({
    providedIn: 'root'
})
export class SolicitudClasificacionService extends SuperService<Solicitud> {
    model = 'solicitudes-asignadas'

    protected override columns: (keyof Solicitud)[] = [
        'id',
        'estatus',
        'created_by',
        'descripcion_problema',
        'fecha_inicio_problematica',
        'empresa_id',
        'empresa_razon_social',
        'empresa_rfc',
        'empresa_nombre_solicitante',
        'empresa_correo_solicitante',
        'empresa_telefono_solicitante',
        'fecha_asignacion',
        'notas_asignacion',
        'observaciones_clasificacion',
        'clasificado_por',
        'fecha_clasificacion'
    ]

    /**
     * Obtiene las solicitudes asignadas al usuario autenticado que están pendientes de clasificación (estatus 'RECIBIDA')
     *
     * @param search - Texto opcional para buscar por descripción o empresa
     * @param page - Número de página (por defecto 1)
     * @param perPage - Cantidad de resultados por página (por defecto 10)
     * @param loader - Muestra loader global animado (por defecto true)
     * @returns Promise con la respuesta paginada de solicitudes asignadas pendientes
     */
    async getSolicitudesPendientes(
        search?: string,
        page = 1,
        perPage = 10,
        loader = true
    ): Promise<StandarResponse<Solicitud[]>> {
        const extraData: Record<string, unknown> = {};

        if (search) {
            extraData['search'] = search;
        }

        return this.get(
            {
                conditionals: {
                    deleted_at: null,
                },
                paginator: {
                    page,
                    per_page: perPage
                },
                extraData,
                loader
            }
        );
    }

    /**
     * Obtiene los catálogos necesarios para la clasificación
     *
     * @param loader - Muestra loader global animado (por defecto true)
     * @returns Promise con los catálogos de clasificación
     */
    async getCatalogos(loader = true): Promise<CatalogosClasificacion> {
        const url = this.url() + '/catalogos';
        const response = await firstValueFrom(this.api.get<CatalogosClasificacion>(url, {}, loader));
        return response.data!;
    }

    /**
     * Obtiene los detalles completos de una solicitud asignada para clasificación
     * Solo funciona si la solicitud está asignada al usuario autenticado
     *
     * @param id - ID de la solicitud
     * @param loader - Muestra loader global animado (por defecto true)
     * @returns Promise con los detalles completos de la solicitud asignada
     */
    async getDetallesParaClasificacion(id: number, loader = true): Promise<Solicitud> {
        const url = this.url() + '/' + id;
        const response = await firstValueFrom(this.api.get<Solicitud>(url, {}, loader));
        return response.data!;
    }

    /**
     * Clasifica una solicitud asignada cambiando su estatus a 'CLASIFICADA'
     * y asignando los datos de clasificación
     *
     * @param id - ID de la solicitud a clasificar
     * @param datosClasificacion - Datos de clasificación (tipo, trámites, nivel gobierno, observaciones)
     * @param loader - Muestra loader global animado (por defecto true)
     * @returns Promise con la respuesta de la operación
     */
    async clasificarSolicitud(
        id: number,
        datosClasificacion: ClasificacionRequest,
        loader = true
    ): Promise<StandarResponse<Solicitud>> {
        const url = this.url() + '/' + id + '/clasificar';
        return firstValueFrom(this.api.put<Solicitud>(url, datosClasificacion, loader));
    }

    /**
     * Obtiene estadísticas de las solicitudes asignadas al usuario autenticado
     *
     * @param loader - Muestra loader global animado (por defecto true)
     * @returns Promise con las estadísticas de solicitudes asignadas
     */
    async getEstadisticas(loader = true): Promise<EstadisticasSolicitudesAsignadas> {
        const url = this.url() + '/estadisticas';
        const response = await firstValueFrom(this.api.get<EstadisticasSolicitudesAsignadas>(url, {}, loader));
        return response.data!;
    }

    /**
     * Busca solicitudes asignadas por texto
     *
     * @param searchText - Texto a buscar en descripción o razón social
     * @param page - Número de página (por defecto 1)
     * @param perPage - Cantidad de resultados por página (por defecto 10)
     * @param loader - Muestra loader global animado (por defecto true)
     * @returns Promise con los resultados de la búsqueda
     */
    async buscarSolicitudes(
        searchText: string,
        page = 1,
        perPage = 10,
        loader = true
    ): Promise<StandarResponse<Solicitud[]>> {
        return this.getSolicitudesPendientes(searchText, page, perPage, loader);
    }
}