// src/app/components/solicitud-creacion/solicitud-creacion.component.ts

import { Component, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup, Validators, FormArray } from '@angular/forms';
import { Router, RouterLink } from '@angular/router';
import { SolicitudService } from '../../../controllers/solicitud.service';
import { CrearSolicitudRequest } from '../../../models/solicitud';
import { EmpresaService } from '../../../controllers/empresa.service';
import { LocalStorageService } from '../../../services/localStorage/local-storage.service';

@Component({
  selector: 'app-solicitudes-form',
  standalone: true,
  imports: [
    CommonModule, 
    ReactiveFormsModule,
    RouterLink,
  ],
  templateUrl: './solicitudes-form.html',
  styleUrls: ['./solicitudes-form.css']
})
export class SolicitudesForm implements OnInit {
  solicitudForm!: FormGroup;
  submitted = false;
  loading = false;

  // Propiedades para la gestión de archivos
  selectedFiles: File[] = [];
  fileErrors: string[] = [];
  readonly maxFileSizeMB = 20;
  readonly allowedFileType = 'application/pdf';

  private fb = inject(FormBuilder);
  private solicitudService = inject(SolicitudService);
  private storage = inject(LocalStorageService)
  private empresaService = inject(EmpresaService)
  private router = inject(Router);

  puedeCrearSolicitud =true

  ngOnInit(): void {
    this.solicitudForm = this.fb.group({
      descripcion_problema: [
        '',
        [
          Validators.required,
          Validators.minLength(20), // Requerimos una descripción más detallada
          Validators.maxLength(1000)
        ]
      ],
      fecha_inicio_problematica: [null, Validators.required],
      evidencias: this.fb.array([]) // Usamos un FormArray para manejar la lista de archivos
    });

    this.verificarSiPuedeCrearSolicitud()
  }

  private async verificarSiPuedeCrearSolicitud(){
    this.puedeCrearSolicitud = !!(await this.empresaService.get({
      conditionals:{
        solicitante_id: this.storage.getUser()?.user.id ?? 0,
        deleted_at:null,
      },
      columns:'id',
      paginator:{
        per_page:1,
      }
    })).data?.length
  }

  // Getter para acceder fácilmente a los controles del formulario
  get f() {
    return this.solicitudForm.controls;
  }

  // Getter para el FormArray de evidencias
  get evidenciasArray() {
    return this.solicitudForm.get('evidencias') as FormArray;
  }

  onFileSelect(event: Event): void {
    const input = event.target as HTMLInputElement;
    if (!input.files) return;

    this.fileErrors = []; // Limpiamos errores anteriores

    const filesToAdd = Array.from(input.files);

    filesToAdd.forEach(file => {
      if (file.type !== this.allowedFileType) {
        this.fileErrors.push(`El archivo "${file.name}" no es un PDF.`);
        return;
      }
      if (file.size > this.maxFileSizeMB * 1024 * 1024) {
        this.fileErrors.push(`El archivo "${file.name}" excede el límite de ${this.maxFileSizeMB}MB.`);
        return;
      }
      // Si es válido, lo añadimos a nuestra lista y al FormArray
      this.selectedFiles.push(file);
      this.evidenciasArray.push(this.fb.control(file));
    });

    // Limpiamos el input para permitir seleccionar el mismo archivo de nuevo si se elimina
    input.value = '';
  }

  removeFile(index: number): void {
    this.selectedFiles.splice(index, 1);
    this.evidenciasArray.removeAt(index);
  }

  async onSubmit(): Promise<void> {
    if (this.solicitudForm.invalid) {
      this.solicitudForm.markAllAsTouched();
      return;
    }

    this.loading = true;

    // Preparar datos para el backend
    const solicitudData: CrearSolicitudRequest = {
      descripcion_problema: this.solicitudForm.value.descripcion_problema,
      fecha_inicio_problematica: this.solicitudForm.value.fecha_inicio_problematica
    };

    // Usar el servicio personalizado para crear la solicitud
    // El API Service ya manejará los errores automáticamente
    const nuevaSolicitud = await this.solicitudService.crearSolicitud(
      solicitudData,
      this.selectedFiles.length > 0 ? this.selectedFiles : undefined
    );

    this.loading = false;

    if (nuevaSolicitud) {
      // Éxito: mostrar mensaje y redirigir
      this.submitted = true;

      // Redirigir después de un breve momento para que el usuario vea el mensaje de éxito
      setTimeout(() => {
        this.router.navigate(['/main/solicitudes/lista']);
      }, 2000);
    }
  }
}