import { inject, Injectable } from "@angular/core";
import { HttpHeadersService } from "../../../../services/http.headers.service";
import { firstValueFrom } from "rxjs";
import { HttpClient } from "@angular/common/http";
import { environment } from "../../../../../environments/environment";
import { Solicitud } from "../../../../models/solicitud";
import { SolicitudesEnProcesoResponse } from "../interfaces/paginacion.interface";

export interface SolicitudEnProcesoOptions{
        textoBusqueda?: string;
        entidadGestionada?: string;
        solicitud_tipo_id?: number;
        fechaInicio?: string;
        fechaFin?: string;
        sinActividadReciente?: boolean;
        page?: number;
        per_page?: number;
        sort_by?: string;
        sort_order?: 'asc' | 'desc';
}

@Injectable({
    providedIn: 'root'
})
export class SolicitudesEnProcesoService {
    private headers = inject(HttpHeadersService)
    private http = inject(HttpClient)
    private apiUrl = environment.api_url;

    public async getSolicitudesEnProceso(opciones: SolicitudEnProcesoOptions): Promise<SolicitudesEnProcesoResponse<Solicitud>> {
        // Limpiar parámetros undefined/vacíos
        const params = Object.fromEntries(
            Object.entries(opciones).filter(([, value]) =>
                value !== undefined && value !== null && value !== ''
            )
        );

        const response = await firstValueFrom(
            this.http.get<SolicitudesEnProcesoResponse<Solicitud>>(
                this.apiUrl + '/api/solicitudes-en-proceso',
                {
                    params,
                    headers: this.headers.createAuthHeaders()
                }
            )
        );

        return response;
    }

    /**
     * Obtiene una solicitud específica por ID
     */
    public async getSolicitudById(id: number): Promise<Solicitud> {
        const response = await firstValueFrom(
            this.http.get<{status: boolean; data: Solicitud}>(
                `${this.apiUrl}/api/solicitudes-en-proceso/${id}`,
                { headers: this.headers.createAuthHeaders() }
            )
        );

        return response.data;
    }

    /**
     * Obtiene el conteo de solicitudes por estado de actividad
     */
    public async getEstadosActividad(): Promise<{
        activas: number;
        atencion: number;
        urgentes: number;
        total: number;
    }> {
        const response = await firstValueFrom(
            this.http.get<{status: boolean; data: {
                activas: number;
                atencion: number;
                urgentes: number;
                total: number;
            }}>(
                `${this.apiUrl}/api/solicitudes-en-proceso/estadisticas-tiempo-actividad`,
                { headers: this.headers.createAuthHeaders() }
            )
        );

        return response.data;
    }
}