import { Component, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router'; // Import Router
import { SolicitudAsignacionController, SolicitudesPendientesOptions, SolicitudPendiente, UsuarioSei } from '../controllers/solicitud-asignacion.controller';
import { LocalStorageService } from '../../../services/localStorage/local-storage.service';
import { SolicitudCatalogoService, CatalogosClasificacion } from '../../../controllers/solicitud-catalogo.service';
import { EstadisticasAsignacion, TopUsuario } from '../services/solicitud-asignacion.service';
import { UsuarioService } from '../../../controllers/usuario.service';
import { Usuario } from '../../../models/usuario';
import { SolicitudService } from '../../../controllers/solicitud.service'; // Import SolicitudService
import { Solicitud } from '../../../models/solicitud';

@Component({
  selector: 'app-solicitudes-asignacion',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule
  ],
  templateUrl: './solicitudes-asignacion.html',
  styleUrl: './solicitudes-asignacion.css'
})
export class SolicitudesAsignacion implements OnInit {
  solicitudes: SolicitudPendiente[] = [];
  usuariosDisponibles: UsuarioSei[] = [];
  loading = false;
  loadingUsuarios = false;
  loadingCatalogos = false;
  loadingEstadisticas = false;
  loadingUsuarioDetails = false;
  loadingUsuarioSolicitudes = false; // New loading state for assigned solicitudes
  submitted = false;

  // Catálogos para filtros
  catalogos: CatalogosClasificacion = {
    tipos: [],
    tematicas: [],
    niveles_gobierno: [],
    dependenciasFederales: [],
    dependenciasEstatales: []
  };

  // Estadísticas
  estadisticas: EstadisticasAsignacion | null = null;

  // Paginación
  currentPage = 1;
  itemsPerPage = 10;
  totalItems = 0;
  totalPages = 0;

  // Filtros
  filtros = {
    search: '',
    estatus: 'RECIBIDA',
    solicitud_tematica_id: null as number | null,
    solicitud_gobierno_nivel_id: null as number | null,
    fecha_creacion_desde: '',
    fecha_creacion_hasta: ''
  };

  // Modal de asignación
  showModalAsignacion = false;
  solicitudSeleccionada: SolicitudPendiente | null = null;
  usuarioSeleccionado = '';
  notasAsignacion = '';
  asignacionLoading = false;

  // Modal de info de usuario
  showUsuarioModal = false;
  selectedUsuario: { usuario: Partial<Usuario>&{ cargo?: string} | null, solicitudesAsignadas: Solicitud[] | null } | null = null; // Add solicitudesAsignadas

  // Estado
  exitMessage = '';
  errors: string[] = [];

  private solicitudAsignacionController = inject(SolicitudAsignacionController);
  private localStorageService = inject(LocalStorageService);
  private solicitudCatalogoService = inject(SolicitudCatalogoService);
  private usuarioService = inject(UsuarioService);
  private solicitudService = inject(SolicitudService); // Inject SolicitudService
  private router = inject(Router);

  ngOnInit(): void {
    this.cargarSolicitudesPendientes();
    this.cargarUsuariosDisponibles();
    this.cargarCatalogos();
    this.cargarEstadisticas();
  }

  async abrirModalUsuario(usuarioStat: TopUsuario): Promise<void> {
    this.loadingUsuarioDetails = true;
    this.loadingUsuarioSolicitudes = true;
    this.showUsuarioModal = true;
    this.selectedUsuario = { ...usuarioStat, usuario: null, solicitudesAsignadas: null };

    try {
      if (usuarioStat.usuario && usuarioStat.usuario.id) {
        // Fetch user details and assigned solicitudes in parallel
        const [fullUserDetails, solicitudesResponse] = await Promise.all([
          this.usuarioService.getUserWithRoles(usuarioStat.usuario.id),
          this.solicitudService.getSolicitudesByUsuarioId(usuarioStat.usuario.id)
        ]);

        this.selectedUsuario = {
          ...usuarioStat,
          usuario: fullUserDetails?? null,
          solicitudesAsignadas: solicitudesResponse.data || []
        };
      } else {
        throw new Error('User ID not available for fetching details.');
      }
    } catch (error) {
      console.error('Error fetching user modal data:', error);
      this.selectedUsuario = { ...usuarioStat, usuario: usuarioStat.usuario, solicitudesAsignadas: [] };
      this.errors.push('No se pudo cargar toda la información del usuario.');
    } finally {
      this.loadingUsuarioDetails = false;
      this.loadingUsuarioSolicitudes = false;
    }
  }

  cerrarModalUsuario(): void {
    this.showUsuarioModal = false;
    this.selectedUsuario = null;
    this.errors = [];
  }

  /**
   * Navegar a la página de detalles de la solicitud
   */
  verDetalles(solicitud: Partial<SolicitudPendiente>): void {
    this.router.navigate(['/main/solicitudes/detalle', solicitud.id]);
  }

  // ... (the rest of the existing methods remain the same)
  /**
   * Cargar solicitudes pendientes de asignar
   */
  async cargarSolicitudesPendientes(page = 1): Promise<void> {
    this.loading = true;
    this.errors = [];

    try {
      // Crear parámetros dinámicamente, incluyendo solo los que tienen valor
      const params: SolicitudesPendientesOptions = {
        page,
        per_page: this.itemsPerPage,
        estatus: this.filtros.estatus,
      };

      if (this.filtros.search) {
        const searchAsNumber = Number(this.filtros.search);
        // Check if search input is a valid integer
        if (!isNaN(searchAsNumber) && Number.isInteger(searchAsNumber)) {
          params.id = searchAsNumber; // Search by ID if it's a number
        } else {
          params.search = this.filtros.search; // Search by text if not a number
        }
      }

      // Agregar otros filtros solo si tienen valor

      if (this.filtros.solicitud_tematica_id) {
        params.solicitud_tematica_id = this.filtros.solicitud_tematica_id;
      }
      if (this.filtros.solicitud_gobierno_nivel_id) {
        params.solicitud_gobierno_nivel_id = this.filtros.solicitud_gobierno_nivel_id;
      }
      // Date filters are only added if they have a value
      if (this.filtros.fecha_creacion_desde) {
        params.fecha_creacion_desde = this.filtros.fecha_creacion_desde;
      }
      if (this.filtros.fecha_creacion_hasta) {
        params.fecha_creacion_hasta = this.filtros.fecha_creacion_hasta;
      }

      console.log('Request params:', params); 

      const result = await this.solicitudAsignacionController.getSolicitudesPendientes(params);

      if (result.success) {
        this.solicitudes = result.solicitudes || [];
        this.currentPage = page;
        this.totalItems = result.pagination?.total_items || 0;
        this.totalPages = result.pagination?.total_pages || 0;
      } else {
        this.errors = result.errors || ['Error al cargar las solicitudes'];
      }
    } catch (error) {
      console.error('Error cargando solicitudes:', error);
      this.errors = ['Error de conexión'];
    } finally {
      this.loading = false;
    }
  }

  /**
   * Cargar usuarios SEI disponibles
   */
  async cargarUsuariosDisponibles(): Promise<void> {
    this.loadingUsuarios = true;

    try {
      const result = await this.solicitudAsignacionController.getUsuariosDisponibles();

      if (result.success) {
        this.usuariosDisponibles = result.usuarios || [];
      } else {
        console.error('Error cargando usuarios:', result.errors);
      }
    } catch (error) {
      console.error('Error cargando usuarios disponibles:', error);
    } finally {
      this.loadingUsuarios = false;
    }
  }

  /**
   * Cargar catálogos para filtros
   */
  async cargarCatalogos(): Promise<void> {
    this.loadingCatalogos = true;

    try {
      this.catalogos = await this.solicitudCatalogoService.getCatalogos(false);
      console.log('Catálogos cargados:', this.catalogos);
    } catch (error) {
      console.error('Error cargando catálogos:', error);
    } finally {
      this.loadingCatalogos = false;
    }
  }

  /**
   * Cargar estadísticas de asignación
   */
  async cargarEstadisticas(): Promise<void> {
    this.loadingEstadisticas = true;

    try {
      const result = await this.solicitudAsignacionController.getEstadisticas();

      if (result.success && result.estadisticas) {
        this.estadisticas = result.estadisticas;
        console.log('Estadísticas cargadas:', this.estadisticas);
      } else {
        console.error('Error cargando estadísticas:', result.errors);
      }
    } catch (error) {
      console.error('Error cargando estadísticas:', error);
    } finally {
      this.loadingEstadisticas = false;
    }
  }

  /**
   * Abrir modal de asignación
   */
  abrirModalAsignacion(solicitud: SolicitudPendiente): void {
    this.solicitudSeleccionada = solicitud;
    this.usuarioSeleccionado = '';
    this.notasAsignacion = '';
    this.showModalAsignacion = true;
    this.errors = [];
  }

  /**
   * Cerrar modal de asignación
   */
  cerrarModalAsignacion(): void {
    this.showModalAsignacion = false;
    this.solicitudSeleccionada = null;
    this.usuarioSeleccionado = '';
    this.notasAsignacion = '';
    this.errors = [];
  }

  /**
   * Asignar solicitud a usuario
   */
  async asignarSolicitud(): Promise<void> {
    if (!this.solicitudSeleccionada || !this.usuarioSeleccionado) {
      this.errors = ['Debe seleccionar un usuario SEI'];
      return;
    }

    this.asignacionLoading = true;
    this.errors = [];

    try {
      const result = await this.solicitudAsignacionController.asignarSolicitud(
        this.solicitudSeleccionada.id,
        {
          usuario_sei_id: parseInt(this.usuarioSeleccionado),
          notas: this.notasAsignacion.trim()
        }
      );

      if (result.success) {
        this.exitMessage = 'Solicitud asignada exitosamente';
        this.submitted = true;

        // Cerrar modal y recargar lista
        setTimeout(() => {
          this.cerrarModalAsignacion();
          this.cargarSolicitudesPendientes(this.currentPage);
          this.submitted = false;
          this.exitMessage = '';
        }, 2000);
      } else {
        this.errors = result.errors || ['Error al asignar la solicitud'];
      }
    } catch (error) {
      console.error('Error asignando solicitud:', error);
      this.errors = ['Error de conexión'];
    } finally {
      this.asignacionLoading = false;
    }
  }

  /**
   * Aplicar filtros
   */
  aplicarFiltros(): void {
    console.log('Applying filters:', this.filtros);
    this.currentPage = 1;
    this.cargarSolicitudesPendientes();
  }

  /**
   * Limpiar filtros
   */
  limpiarFiltros(): void {
    this.filtros = {
      search: '',
      estatus : 'RECIBIDA',
      solicitud_tematica_id: null,
      solicitud_gobierno_nivel_id: null,
      fecha_creacion_desde: '',
      fecha_creacion_hasta: ''
    };
    this.currentPage = 1;
    this.cargarSolicitudesPendientes();
  }

  /**
   * Navegación de paginación
   */
  cambiarPagina(page: number): void {
    if (page >= 1 && page <= this.totalPages) {
      this.cargarSolicitudesPendientes(page);
    }
  }

  /**
   * Formatear fecha
   */
  formatearFecha(fechaString: string): string {
    return this.solicitudAsignacionController.formatearFecha(fechaString);
  }

  /**
   * Calcular días transcurridos
   */
  calcularDiasTranscurridos(fechaString: string): number {
    return this.solicitudAsignacionController.calcularDiasTranscurridos(fechaString);
  }

  /**
   * Obtener clase CSS para estatus
   */
  getEstatusClass(estatus: string|undefined|null
  ): string {
    return this.solicitudAsignacionController.getEstatusClass(estatus??'');
  }

  /**
   * Obtener icono para estatus
   */
  getEstatusIcon(estatus: string): string {
    return this.solicitudAsignacionController.getEstatusIcon(estatus);
  }

  /**
   * Verificar si el usuario es administrador
   */
  get esAdmin(): boolean {
    return this.localStorageService.esAdmin();
  }

  /**
   * Verificar si el usuario tiene rol de solicitante
   */
  get esSolicitante(): boolean {
    const rol = this.localStorageService.getRolUser();
    return rol?.toLowerCase() === 'solicitante';
  }

  /**
   * Obtener nombre del usuario seleccionado
   */
  get nombreUsuarioSeleccionado(): string {
    const usuario = this.usuariosDisponibles.find(u => u.id.toString() === this.usuarioSeleccionado);
    return usuario ? `${usuario.name} (${usuario.email})` : '';
  }

  /**
   * Generar array de páginas para paginación
   */
  get paginas(): number[] {
    const paginas: number[] = [];
    const maxPaginasMostradas = 5;

    if (this.totalPages <= maxPaginasMostradas) {
      for (let i = 1; i <= this.totalPages; i++) {
        paginas.push(i);
      }
    } else {
      const inicio = Math.max(1, this.currentPage - 2);
      const fin = Math.min(this.totalPages, inicio + maxPaginasMostradas - 1);

      for (let i = inicio; i <= fin; i++) {
        paginas.push(i);
      }
    }

    return paginas;
  }

  /**
   * Verificar si hay filtros activos
   */
  get hayFiltrosActivos(): boolean {
    return Object.values(this.filtros).some(valor => valor !== '');
  }
}