import { BaseModel } from "./base.model";
import { Empresa } from "./empresa";
import { SolicitudAccion } from "./solicitud.accion";
import { SolicitudAsignacion } from "./solicitud.asignacion";
import { SolicitudComentario } from "./solicitud.comentario";
import { SolicitudEvidencia } from "./solicitud.evidencia";
import { SolicitudGobiernoNivel } from "./solicitud.gobierno.nivel";
import { SolicitudTematica } from "./solicitud.tematica";
import { SolicitudTipo } from "./solicitud.tipo";
import { Usuario } from "./usuario";

/**
 * Enumeración para los posibles estatus de una solicitud
 */
export enum SolicitudEstatus {
    RECIBIDA = 'RECIBIDA',
    EN_PROCESO = 'EN PROCESO',
    RESUELTA = 'RESUELTA'
}

/**
 * Enumeración para el tipo de persona de la empresa
 */
export enum EmpresaTipoPersona {
    FISICA = 'fisica',
    MORAL = 'moral'
}

/**
 * Interfaz para crear una nueva solicitud
 * Solo incluye los campos que el usuario puede proporcionar
 */
export interface CrearSolicitudRequest {
    /** Descripción detallada del problema (requerido) */
    descripcion_problema: string;

    /** Fecha y hora en que inició la problemática (requerido) */
    fecha_inicio_problematica: string | Date;

    /** Archivos de evidencia en formato PDF (opcional) */
    evidencias?: File[];
}

/**
 * Interfaz para actualizar una solicitud existente
 * To dos los campos son opcionales ya que se puede actualizar parcialmente
 */
export interface ActualizarSolicitudRequest {
    /** Descripción detallada del problema */
    descripcion_problema?: string;

    /** Fecha y hora en que inició la problemática */
    fecha_inicio_problematica?: string | Date;
}

/**
 * Interfaz para solicitar datos de clasificación de una solicitud
 */
export interface ClasificacionRequest {
    /** ID del tipo de solicitud (requerido) */
    solicitud_tipo_id: number;

    /** ID de la trámite de la solicitud (requerido) */
    solicitud_tematica_id: number;

    /** Nombre de la otra temática (opcional) */
    solicitud_tematica_otro?: string;

    /** ID del orden de gobierno (requerido) */
    solicitud_gobierno_nivel_id: number;

    /** ID de la dependencia (opcional) */
    solicitud_dependencia_id?: number;

    /** Nombre de la otra dependencia (opcional) */
    otra_dependencia?: string;

    /** Observaciones de la clasificación (opcional) */
    observaciones_clasificacion?: string;
}

/**
 * Interfaz para Dependencia
 */
export interface Dependencia {
    id: number;
    nombre: string;
}

/**
 * Interfaz para catálogos de clasificación
 */
export interface CatalogosClasificacion {
    /** Lista de tipos de solicitud disponibles */
    tipos: SolicitudTipo[];

    /** Lista de trámites de solicitud disponibles */
    tematicas: SolicitudTematica[];

    /** Lista de niveles de gobierno disponibles */
    niveles_gobierno: SolicitudGobiernoNivel[];

    /** Lista de dependencias disponibles */
    dependencias: Dependencia[];
}

/**
 * Interfaz para estadísticas de clasificación
 */
export interface EstadisticasClasificacion {
    /** Número de solicitudes recibidas (pendientes de clasificación) */
    solicitudes_recibidas: number;

    /** Número de solicitudes en proceso (ya clasificadas) */
    solicitudes_en_proceso: number;

    /** Total de solicitudes en el sistema */
    total_solicitudes: number;
}

/**
 * Interfaz principal que representa una Solicitud en el sistema
 * Incluye tanto los datos de la solicitud como un snapshot de los datos de la empresa
 */
export interface Solicitud extends BaseModel {
    // ===== DATOS GENERADOS POR EL SISTEMA (readonly) =====
    readonly estatus?: SolicitudEstatus;
    readonly created_by?: number | null;

    // ===== DATOS DE CLASIFICACIÓN (asignados posteriormente por un USUARIO INTERNO usando api dedicada) =====
    readonly solicitud_tipo_id?: number | null;
    readonly solicitud_tematica_id?: number | null;
    readonly solicitud_tematica_otro?: string | null;
    readonly solicitud_gobierno_nivel_id?: number | null;
    readonly solicitud_dependencia_id?: number | null;
    readonly otra_dependencia?: string | null;
    readonly observaciones_clasificacion?: string | null;
    readonly clasificado_por?: number | null;
    readonly fecha_clasificacion?: string | Date | null;

    // ===== DATOS DE ASIGNACIÓN (para solicitudes asignadas a usuarios SEI) =====
    readonly fecha_asignacion?: string | Date | null;
    readonly asignado_por?: Usuario | null;
    readonly notas_asignacion?: string | null;

    // ===== DATOS PROPORCIONADOS POR EL USUARIO EXTERNO =====
    descripcion_problema: string;
    fecha_inicio_problematica: string | Date;

    // ===== SNAPSHOT DE DATOS DE LA EMPRESA (generados por el sistema) =====
    readonly empresa_id ?: number;
    readonly empresa_tipo_persona?: EmpresaTipoPersona;
    readonly empresa_rfc?: string;
    readonly empresa_razon_social?: string;
    readonly empresa_nombre_comercial?: string | null;
    readonly empresa_sector_comercial_id?: number | null;
    readonly empresa_actividad_economica_id?: number | null;
    readonly empresa_tipo_empresa_id?: number | null;
    readonly empresa_pais_procedencia?: string;
    readonly empresa_nombre_solicitante?: string;
    readonly empresa_cargo_solicitante?: string;
    readonly empresa_correo_solicitante?: string;
    readonly empresa_telefono_solicitante?: string;
    readonly empresa_municipio_id?: number | null;
    readonly empresa_numero_empleados_directos?: number | null;

    // ===== RELACIONES (cargadas opcionalmente) =====
    empresa?: Empresa;
    solicitud_tipo?: SolicitudTipo;
    solicitud_tematica?: SolicitudTematica;
    solicitud_gobierno_nivel?: SolicitudGobiernoNivel;
    dependencia?: Dependencia;
    creador?: Usuario;
    evidencias?: SolicitudEvidencia[];
    comentarios ?: SolicitudComentario[];
    acciones ?: SolicitudAccion[];
    asignacion_actual?: SolicitudAsignacion;
}