import { Component, inject, OnInit } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute, RouterLink } from '@angular/router';
import { Location } from '@angular/common'; // Import Location
import { Solicitud } from '../../../models/solicitud';
import { SolicitudService } from '../../../controllers/solicitud.service';
import { SolicitudEvidenciaService } from '../../../controllers/solicitud-evidencia.service';
import { ComentariosBox } from "../shared/comentarios-box/comentarios-box";
import { SolicitudInfo } from "../shared/solicitud-info/solicitud-info.component";
import { SolicitudDocumentos } from "../shared/solicitud-documentos/solicitud-documentos.component";
import { LocalStorageService } from '../../../services/localStorage/local-storage.service';

@Component({
  selector: 'app-solicitud-detalle',
  imports: [
    FormsModule,
    RouterLink,
    ComentariosBox,
    SolicitudInfo,
    SolicitudDocumentos
  ],
  templateUrl: './solicitud-detalle.html',
  styleUrl: './solicitud-detalle.css'
})
export class SolicitudDetalle implements OnInit {
  // Datos principales
  solicitud: Solicitud | null = null;

  // Estados de UI
  loading = false;
  error: string | null = null;

  // Services
  private route = inject(ActivatedRoute);
  private solicitudService = inject(SolicitudService);
  private evidenciaService = inject(SolicitudEvidenciaService);
  public storage = inject(LocalStorageService);
  private location = inject(Location); // Inject Location service

  ngOnInit() {
    // Obtener el ID de la solicitud de la ruta
    const id = this.route.snapshot.paramMap.get('id');
    if (id) {
      this.cargarDatos(parseInt(id));
    } else {
      this.error = 'ID de solicitud no proporcionado';
    }
  }

  /**
   * Navega hacia atrás en el historial del navegador.
   */
  goBack(): void {
    this.location.back();
  }



  /**
   * Carga todos los datos necesarios para el detalle
   */
  private async cargarDatos(solicitudId: number) {
    this.loading = true;

    // Cargar solicitud con relaciones
    this.solicitud = await this.solicitudService.find(solicitudId, {
      relations: ['evidencias', 'comentarios.creador']
    }) || null;

    this.loading = false;
  }
  /**
   * Obtiene las iniciales de un nombre
   */
  getIniciales(nombre: string): string {
    if (!nombre) return 'NA';
    return nombre
      .split(' ')
      .map(word => word.charAt(0).toUpperCase())
      .slice(0, 2)
      .join('');
  }

  /**
   * Obtiene el icono según el tipo de archivo
   */
  getFileIcon(fileName: string): string {
    const extension = fileName.toLowerCase().split('.').pop();

    switch (extension) {
      case 'pdf':
        return 'bi-file-earmark-pdf text-danger';
      case 'doc':
      case 'docx':
        return 'bi-file-earmark-word text-primary';
      case 'xls':
      case 'xlsx':
        return 'bi-file-earmark-excel text-success';
      case 'ppt':
      case 'pptx':
        return 'bi-file-earmark-slides text-warning';
      case 'jpg':
      case 'jpeg':
      case 'png':
      case 'gif':
        return 'bi-file-earmark-image text-info';
      case 'txt':
        return 'bi-file-earmark-text text-secondary';
      default:
        return 'bi-file-earmark text-muted';
    }
  }

  /**
   * Abre una evidencia en una nueva ventana para visualización
   */
  async verEvidencia(evidenciaId: number): Promise<void> {
    const exito = await this.evidenciaService.verEvidencia(evidenciaId);
    if (!exito) {
      console.error('No se pudo visualizar la evidencia');
    }
  }

  /**
   * Maneja la actualización de documentos desde el componente hijo
   */
  async onDocumentosActualizados(): Promise<void> {
    if (this.solicitud) {
      await this.cargarDatos(this.solicitud.id);
    }
  }


}