import { Injectable, inject } from "@angular/core";
import { HttpClient } from "@angular/common/http";
import { environment } from '../../../../../../environments/environment';
import { Observable } from 'rxjs';
import { EstadisticasResponse } from '../interfaces/estadisticas.interface';

export interface FiltrosSolicitudesResueltas {
    folio?: number;
    rfc?: string;
    empresa?: string;
    tematica_id?: number;
    gobierno_nivel_id?: number;
    tipo_id?: number;
    fecha_inicio?: string;
    fecha_fin?: string;
    page?: number;
    per_page?: number;
}

// Interfaz para datos de solicitud resuelta según OpenAPI
export interface SolicitudResueltaData {
    id: number;
    estatus: string;
    empresa_rfc?: string;
    empresa_razon_social?: string;
    empresa_nombre_comercial?: string;
    created_at: string;
    descripcion_problema?: string;
    fecha_inicio_problematica?: string;
    fecha_clasificacion?: string;
    empresa?: {
        id: number;
        rfc: string;
        razon_social: string;
        nombre_comercial: string;
    };
    solicitud_tipo?: {
        id: number;
        nombre: string;
        descripcion: string;
    };
    solicitud_tematica?: {
        id: number;
        nombre: string;
        descripcion: string;
    };
    solicitud_tematica_otro?: string | null;
    solicitud_gobierno_nivel?: {
        id: number;
        nombre: string;
        descripcion: string;
    };
    creador?: {
        id: number;
        name: string;
        email: string;
    };
    asignado_a?: {
        id: number;
        usuario_sei_id: number;
        estatus: string;
        usuario_sei: {
            id: number;
            name: string;
            email: string;
        };
    };
}

export interface SolicitudesResueltasResponse {
    status: boolean;
    message: string;
    data: SolicitudResueltaData[];
    page: number;
    per_page: number;
    total_pages: number;
    total_items: number;
}

export interface DetallesCompletosResponse {
    status: boolean;
    message: string;
    data: {
        folio: number;
        solicitud: SolicitudResueltaData;
        apartado_i: Record<string, unknown>;
        apartado_ii: Record<string, unknown>;
    };
}

@Injectable({
    providedIn: 'root'
})
export class SolicitudResueltaService {
    private http = inject(HttpClient);
    private baseUrl = environment.api_url + '/api/solicitudes-resueltas';

    /**
     * Obtiene solicitudes concluidas con filtros específicos según la API OpenAPI
     * @param filtros Parámetros de filtrado y paginación
     * @returns Observable con respuesta paginada de solicitudes concluidas
     */
    getSolicitudesResueltas(filtros?: FiltrosSolicitudesResueltas): Observable<SolicitudesResueltasResponse> {
        const params: Record<string, string | number> = {
            page: filtros?.page || 1,
            per_page: filtros?.per_page || 20
        };

        // Agregar filtros si existen
        if (filtros) {
            if (filtros.folio) params['folio'] = filtros.folio;
            if (filtros.rfc) params['rfc'] = filtros.rfc;
            if (filtros.empresa) params['empresa'] = filtros.empresa;
            if (filtros.tematica_id) params['tematica_id'] = filtros.tematica_id;
            if (filtros.gobierno_nivel_id) params['gobierno_nivel_id'] = filtros.gobierno_nivel_id;
            if (filtros.tipo_id) params['tipo_id'] = filtros.tipo_id;
            if (filtros.fecha_inicio) params['fecha_inicio'] = filtros.fecha_inicio;
            if (filtros.fecha_fin) params['fecha_fin'] = filtros.fecha_fin;
        }

        return this.http.get<SolicitudesResueltasResponse>(this.baseUrl, { params });
    }

    /**
     * Obtiene detalles completos de una solicitud resuelta
     * @param id ID de la solicitud
     * @returns Observable con detalles completos de la solicitud
     */
    getDetallesCompletos(id: number): Observable<DetallesCompletosResponse> {
        const url = `${this.baseUrl}/${id}/detalles-completos`;
        return this.http.get<DetallesCompletosResponse>(url);
    }

    /**
     * Obtiene estadísticas de solicitudes concluidas
     * @param periodo Periodo para estadísticas (dia, semana, mes, año)
     * @param limit Límite de resultados
     * @returns Observable con estadísticas
     */
    getEstadisticas(periodo = 'mes', limit = 10): Observable<EstadisticasResponse> {
        const params = { periodo, limit };
        const url = `${this.baseUrl}/estadisticas`;
        return this.http.get<EstadisticasResponse>(url, { params });
    }

    /**
     * Genera y descarga reporte Excel de solicitudes concluidas
     * @param filtros Parámetros de filtrado para el reporte
     * @returns Observable con el Blob del archivo Excel para descarga
     */
    generarReporteExcel(filtros?: FiltrosSolicitudesResueltas): Observable<Blob> {
        const params: Record<string, string | number> = {};

        // Agregar filtros si existen
        if (filtros) {
            if (filtros.folio) params['folio'] = filtros.folio;
            if (filtros.rfc) params['rfc'] = filtros.rfc;
            if (filtros.empresa) params['empresa'] = filtros.empresa;
            if (filtros.tematica_id) params['tematica_id'] = filtros.tematica_id;
            if (filtros.gobierno_nivel_id) params['gobierno_nivel_id'] = filtros.gobierno_nivel_id;
            if (filtros.tipo_id) params['tipo_id'] = filtros.tipo_id;
            if (filtros.fecha_inicio) params['fecha_inicio'] = filtros.fecha_inicio;
            if (filtros.fecha_fin) params['fecha_fin'] = filtros.fecha_fin;
        }

        const url = environment.api_url + '/api/reporte/solicitudes-resueltas';
        return this.http.get(url, {
            params,
            responseType: 'blob'
        });
    }
}